INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p989277-ee201', 'stk-user6171', 'EE 201', 'info', '{"desc": "المادة اشوفها مادة قريد وكانت سهلة خصوصا لطلاب الكهربا لأنها كلها تعتبر اساسيات للكهرباء ولابها بسييييط ومافيه بريلاب وشغله كان خفافي\n\nاهم شابتر كان 4 لأنه تقريبا راح تستخدمه على طول بعدين في باقي الدروس\nوتقريبا اصعب شيء كان الامبليفاير اللي هو شابتر 5 لأنه لو لعبوا بالاسئلة حقتوا كان اكثر الطلاب جابوا العيد… بس لو فهمت كيف تحلل اي دائرة فيها امبليفاير خلاص بتصير سهلة\n\nكتابي كان electric circuits ninth edition , nilsson riedel PEARSON", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-201-electric-circuits-i/120694/2", "user": "user6171", "ts": 1329649948000, "tid": 120694, "pn": 2}}', 1329649948000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p993707-ee201', 'stk-math_lover', 'EE 201', 'info', '{"desc": "مادة هذي تعتبر من اسهل مواد الكهرباء و حرام واحد ما يأخذ فيها قريد…عموما تتكلم عن الاساسيات و طرق تحليل الدوائر الكهربائية…بصراحة المادة كانت روعة إلا نهاية شابتر 7 كان فيه لحس شوي بالنسبة لي…لاب المادة هذي خفيف مرة و ما يحتاج الى جهد كبير ايضا…بالتوفيق للجميع", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-201-electric-circuits-i/120694/3", "user": "math_lover", "ts": 1330247261000, "tid": 120694, "pn": 3}}', 1330247261000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p993856-ee201', 'stk-user7238', 'EE 201', 'info', '{"desc": "المااده من اهم الموااد في الكهرب وايضاً سهله\n\nالكورس عن تحليل الدوائر الكربائيه\nواكثر الطرق في شابتر 4\nثم شابتر 5 عن الامبليفاير سهل\n6و7 عن تحليل الدوائر الي فيها كباستور او اندكتور\n\nوثم شابتر 9 سهل وهو اعاده لشابتر 4 بس بالنسبه لac وفيه كم حاجه زياده\nواخيراً شابتر 10 عن الباور في ac وهذا الشابتر كان بالنسبه لي الاصعب\nبس ممكن لانه كان اخر الدراسه علشان كذه حسيته صعب\n\nاهم حااجه في الماااده البراااكتس\nوالهوموركات الي تجي من القسم في العااده مهمه جداً\nو تجي فيها اسئله اصعب من الاولد اكزام", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-201-electric-circuits-i/120694/4", "user": "user7238", "ts": 1330256185000, "tid": 120694, "pn": 4}}', 1330256185000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1022769-ee201', 'stk-_xbx', 'EE 201', 'info', '{"desc": "أساس الحقيقي لكثير من المواد\nلازم الواحد يحط في باله أقل أقل شي يأخذ b+ أو b لأنو في مواد كثيرة إذا مو كلها تعتمد عليها\n\nأذكر بعد ما خلصت المادة رجعت أذاكرها لأنو في أشياء كنت مش فاهمها", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-201-electric-circuits-i/120694/6", "user": "_XBX", "ts": 1334492475000, "tid": 120694, "pn": 6}}', 1334492475000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1025096-ee201', 'stk-faisal91', 'EE 201', 'info', '{"desc": "ولا ازيد على كلااام الي قبلي\nبس حبيت انبه الطلاب الي اول مرة ياخذونه ترى الكورس ما راح يكون سهل بالنسبة لهم وهم يدرسونه… انا كنت اعتبره صعب نوعا ما (يوم كنت آخذه) ويبيله براكتس قد ما تقدر… بس ميزة الكورس هذا انه مترابط… يعني انا اذكر دخلت الفاينل وما فتحت شي من الماتيريال حق ميجر 1 ومجير 2 لانك خلاص بتتعود عليها وبتمشي معاااك بقية الكورس نفس المواضيع والطرق حقت تحليل الدوائر الكهربائيه\nكل طلاب الكهرب وانا منهم نشوف الكورس هذا سهل وتافه بعد ما تعودنا على الدوائر الكهربائيه … بس الطالب الي يدرس الكورس ما راح يحس بسهولته الا اذا خلصه واخذ كورسات تعتمد عليه", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-201-electric-circuits-i/120694/7", "user": "FAISAL91", "ts": 1334868090000, "tid": 120694, "pn": 7}}', 1334868090000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1167580-ee201', 'stk-jack_sparrow', 'EE 201', 'info', '{"desc": "أنــآ أخذتهآ ترم 121\nالمتيريل كالتآلي :\n\nشـــآبتر 1 و 2 يتكلم عن قوآنين آوم وكريشووف وكذلك البور والاينيرجي…سهل جدا\nشــآبتر 3 يتكلم عن تكنيك غير كيرشوف ل لتحليل الدوآئر الكهربآئية مثـل :\nنود فولتج لو - وميش اناليسيس … الكرنت ديفآيدر والفولتج ديفآيدر رول …وطبعا هالتكنيك بيستمر معك الى نهآية الترم …يجب عليك فهمهآ بكل الحآلات الشــآذه فيهآ …\nشآبتر 4 يتكلم عن ثفنن ونورتن سيركت وكذلك السورس ترانسفورميشن …مهم وكذلك فيه صعوبه قليــله ,لان عندك يمكن 4 تكنيك لايجــآد ثفنن او نورتن سيركت …ولازم تعرف متى تستخدم كل وآحده …لانه في الميجر يمكن يعطونك سيركت مآتقدر تحللهآ الا بطريقة وآحده …\nشآبتر 5 مآ أخذنآه …\nشآبتر 6 يتكلم عن الايندكتورز والكبآسيتورز …وكيفيه ايجآد الايكويفيلنت اندكتنس او كباسيتنس\n\nشآبتر 7 يتكلم عن النآتشرل والستيب ريسبونس في rc , rl بآرآلل أو سيريز سيركتز \"فيرست ديفرنشل ايكويشن \"\nفيه صعـــوبة قليله واذا حفظت القوآنين وفهمت الافكآر الاسآسية بتمشي وبترتآح في هالشــآبتر\n\nشآبتر 8 يتكلم عن النآتشرل والستيب ريسبونس في rlc بآرآلل أو سيريز سيركتز \"سكند ديفرنشل ايكويشن \"\nنفس شآبتر 7 ومستوى الصعوبه اصعب بقليل من 7 بس نفس الكلآم اذا حفظت القوآنين وعرفت كيف تمشي من البدآية بترتآح …\n\nأخر شآيتر 9 يتكلم عن اللي درسنآه في شآيتر 1و2و3و4 بس هنآ بيكون الكرنت او الفولتج سورس على شكل سينوسويدل ويف … طبعا هنــآك خطــوتين تسويهآ في البدآية وخلاص تحل السيركت كأنهآ مسألة من شآبتر 1او2او3او4 …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-201-electric-circuits-i/120694/11", "user": "jack_sparrow", "ts": 1358857437000, "tid": 120694, "pn": 11}}', 1358857437000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1319191-ee201', 'stk-i.s.w.r.t.w', 'EE 201', 'info', '{"desc": "اخذت الكورس ترم 131\n\nجودة المقرر بشكل عام:\n\nالمقرر مهم لطالب الهندسة الكهربائية ، حيث ان الكورس يعد من اهم الكورسات التى ينبني عليها معظم الكورسات القادمة في التخصص .\n\nالمواضيع التي يغطيها المقرر :\n\nالمقرر يغطي مواضيع اساسية بعضها البسيط (أكثرها) ، وبعضها صعبة (قليلاُ) ، ولكن مع التدرب وحل الامثلة تصبح سهلة جدا .\n\nمن شابتر 1 - 4 ، تعتبر اساسيات مهمة ، وفهمها راح يسهل عليك الكورس كامل ، طبعا هي مو صعبة ولكن لازم تحل امثلة على هذي الـ chapters.\n\nشابتر 5 محذوف وليس في المقرر ( هو جزء من ee 203 وراح يدرس اظن من كتاب اخر)\n\nشابتر 6 سهل ولا فيها صعوبة ، يعطي مقدمة عن الـ Inductors و الـ Capacitor .\nطبعا كل واحد له قانون تجيب الفولت والتيار ، فيه معلومة يجهلها الكثير ممكن تسبب مشاكل ، وهي :\n\nفي الـ Inductor :\nالتيار ما يتغير بشكل سريع المقصود Instantaneously ، بعكس الجهد .\n\nاما في الـ Capacitor :\nالجهد ما يتغير بسرعة ، بعكس التيار .\n\nوهذي المعلومات بعض المدرسين ممكن مايركز عليها ، ولكن مهمة .\n\nشابتر 7 :\nيتكلم عن الـ RC او الـ RL :\n\nRC: دائرة تحتوى على resistor and capacitor\nRL: دائر تحتوى على Inductor and resistor\n\nالشابتر شوي فيه صعوبة ، لذلك لابد من حل الامثلة ، الصعوبة تكمل انا نتعامل مع differential equations وهي شوي معقدة .\n\nفيه ترك يجي في الاسئلة سواً في الكتاب او الميجر ، ان الدائرة معقدة ولا تقدر تشتغل عليها ، عادةً بسبب وجود Independente source الحل سهل جدا ، بسطها بـ Thevinen equavlent circuit (شابتر 4 ) ، خل دكتورك يشرحها لك .\n\nشابتر 8 :\n\nبالنسبة لي اشوفه systematic ، طريقة ثابتة للحل ، انك تعرف نوع الـ response اولا ، وعندك ثلاث انواع ، كل نوع له معادلة ، الى يخلي هذا الشابتر صعب هو انه RLC يعني الثلاثة مع بعض ، Capacitor , Inductor and resistor . والمعدلات ( differential equations ) من الدرجة الثانية .\n\nشابتر 9 :\n\nحلو وسهل ولذيذ ، ولكن لازم تعرف تستخدم الالة ، وتذاكره ، لأن في الفاينل جابوا اسئلة كثيرة عليه وبعض الشباب ما ذاكره ، وإذا كنت الكتركل ، راح تستخدمه في EE213 .\n\nالمذاكرة :\n\nافضل شي الكتاب ، حل اسئلة الـ assesment problems وفي نهايتها راح يقولك حل السؤال الفلاني من نهاية الكتاب ، حله ، وقبل الميجر خذا اول اقزامز ، بالنسبة للفاينال ما فيه اولد اقزامز ، لذلك حل اسئلة اخر الكتاب ، شوف الصعب وحلها ، وشيك المانيوال .\n\nلا تنقل الواجب ابدا ، حلها بنفسك وبعد التصحيح شيك على اخظائك ، واغتنم الساعات المكتبية .\nالكلاس ورك عليه 25٪ لذلك اغتنم كل كويز وحاول انك ما تغيب .\n\nhttps://www.dropbox.com/s/4npelv952lhkvy4/EE-202-131-Syllabus%255b1%255d.docx\n\nبالتوفيق 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-201-electric-circuits-i/120694/16", "user": "I.S.W.R.T.W", "ts": 1389723711000, "tid": 120694, "pn": 16}}', 1389723711000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1363216-ee201', 'stk-confident', 'EE 201', 'info', '{"desc": "سمستر ١٣٢\n\nمادة اشوفها سهله على طلاب الالكترك اللي يحبون الدوائر لكن طلاب الاندستريال اشوفهم مستصعبينها جدا\nالكتاب ممتاز جدا في شرح الكونسبت مع الامثلة والسليوشن متوفر في المنتدى\n\nاخذتها مع دكتور بلغنيم وانصح فيه ، شريح ماشالله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-201-electric-circuits-i/120694/21", "user": "confident", "ts": 1399678155000, "tid": 120694, "pn": 21}}', 1399678155000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1382408-ee201', 'stk-user8577', 'EE 201', 'info', '{"desc": "ee202\n\nبالنسبة لطلاب الكهرباء فهي مادة جدا اساسية ولازم تفهمها … طلاب التخصصات اللي بياخذوا بعدها ee203 فهم هالكورس بيساعدك في الإلكترونكس … أما الطلاب اللي ما تفتح لهم شي فالله يعينكم المادة يبغى لها شوية جهد.\n\nالمواضيع التي يغطيها المقرر :\n\nببساطة هي مادة تعلمك طرق تحليل الدوائر الكهربائية … مادة ماهي متشعبة بمعنى أن المادة أغلبها تدور حول KVL و KCL في البداية تكون بسيطة بعدين تصعب شوي لما تدخل non-linear elements مثل الكابستر والإندكتر واخر شي جزء الكومبلكس واللي صعوبته في التعامل مع الكومبلكس و التحويل له.\n\nالكتاب المستخدم للمقرر:\nكتاب جيد وواضح\n\nالأسئلة والأمثلة المستخدمة في المقرر:\n\nاسئلة الهومورك حلها اول شي وبعدين ارجع شوف كم سؤال صعب من الكتاب لتأكيد فهمك … بعض اسئلة الكتاب جيدة\n\nمدى فائدته في الناحية التطبيقية:\n\nبالنسبة لطلاب الكهرباء راح تستخدمه في كثير من كورساتك ففهم الأساسيات بيريحك في المستقبل.\n\nكثير من دكاترة القسم بيدرسوها بس في كم دكتور غالبا بينزلوها كل فصل مثل: بالغنيم, الأحمري. دكتور كويس بيريحك في هالكورس بس يبقى كورس مقدور عليه كسلف ستدي.\nغالبا الفاينال أصعب من المياجر.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-201-electric-circuits-i/120694/22", "user": "user8577", "ts": 1403690804000, "tid": 120694, "pn": 22}}', 1403690804000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1403650-ee201', 'stk-user2352', 'EE 201', 'info', '{"desc": "هذا الكتاب مبسط ومفيد جدا في شرح محتويات الكورس وفيه مسائل كثيرة محلولة شبيهه بمسائل الهوموركات والمياجر إذا ماكانت نفسها\nhttp://www.stu.edu.vn/uploads/documents/030409-224833.pdf", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-201-electric-circuits-i/120694/23", "user": "user2352", "ts": 1412176867000, "tid": 120694, "pn": 23}}', 1412176867000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1420410-ee201', 'stk-user8581', 'EE 201', 'info', '{"desc": "الكورس في السابق كان اسمه EE201 لكن حاليا صار EE202 واللاب EE212 وهم كورسين منفصلين و 212 كوريكويست ل 202\nطبعا اللاب EE212 ياخذون الاندستريال والكنترول و الـ COE فقط\n\nجودة المقرر بشكل عام :\nممتاز وفادني بشكل كبير خصوصا لو كنت كهرب لأنه يغطي الاساسيات في الـ circuit مع شوية اضافات . المادة سهلة خصوصا الشباتر 1-4 اما الشباتر 6 & 7 & 8 مترابطين مع بعض فحاول تفهم وتراجعهم اول بأول اما شابتر 9 فهو سهل راح تبطق الي خذته في الشباتر السابقة اللهم مع complex numbers . المادة ينفع معاها السيلف ستدي لكن اهم شي هي التدرب وحل مسائل كثر ماتقدر خصوصا اسئلة الهوموركات\n\nالمواضيع التي يغطيها المقرر :\nCircuits Variables, Sources, Power and Energy\nOhm’s Law, KCL, KVL, Dependent Sources\nResistive Circuits, Nodal Analysis\nMesh Analysis, Source Transformation\nThevenin and Norton Equivalent Circuits\nMaximum Power Transfer, Superposition\nInductors, Capacitors first & second order\nSinusoidal & Frequency Domain Analysis\n\nالكتاب المستخدم للمقرر & الأسئلة والأمثلة المستخدمة في المقرر :\nممتاز والشرح واضح وبالخطوات وبعد كل جزء من الدرس فيه example و check points\nحاول تخليه مرجعك في المذاكرة من بداية السمستر لأنه احيانا يشرح بعض الأفكار بشكل مطول ولو كنت متوهق قبل الميجر ومضغوط ماراح يفيدك .\n\nإضافات :\n- لو مافهمت شي او طحت عند دكتور شرحه سيئ فاليوتيوب فيه شروحات كثير لأغلب الماتيريال + حوال تـنزل عند دكتور شرحه ممتاز عشان يريحك والأفضل بالتدريج هم : زيدوري , بالغنيم ,الأخضر\n-المياجر نصها رتين و خيارات اما الفاينل مب ثابت في 141 خلوه خيارات بس\nحاول تبدع في الميجر الأول لأن الثاني يكون شوي اصعب من الأول + الكورس افرج\n\nسلايدات واولداقزامات للمياجر + كويزات قديمة\nhttp://faculty.kfupm.edu.sa/EE/adil/teaching.htm\nاولداقزامات للفاينل\nhttps://www.mediafire.com/?3o1juayk2uvcqy5", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-201-electric-circuits-i/120694/26", "user": "user8581", "ts": 1421613493000, "tid": 120694, "pn": 26}}', 1421613493000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1421175-ee201', 'stk-magbool', 'EE 201', 'info', '{"desc": "أخذتها في ترم 141 مع د.عبد الله الأحمري\n\nجودة المقرر بشكل عام :\nمقرر سهل وأفكاره مترابطة ومواضيعه قليلة والأساسيات تتكرر على طول .\nيعني ممكن تطلع بقريد جيد من المادة بجهد متوسط .\n\nالمواضيع التي يغطيها المقرر\nشابتر 1-3 : أساسيات الدوائر الكهرائية، تعطيك عناصر الدوائر زي الكرنت والفولتج سورس والرزيستر والتوصيل على التوالي أو التوازي، فهم الكورس يعتمد بشكل كبير على فهم هذي الأساسيات .\nشابتر 4: أطول وأهم شابتر ، يعطيك بعض الطرق لتحليل الدوائر الكهربائية .\nشاتبتر 6 : يعرف عنصرين جديدين هما الكابيستر والاندكتر .\nشابتر 7، 8 : أصعب شابترين في المنهج ، تستخدم فيه دفرنشيال اكويشنز ، فكرة الشابترين هي تحليل الدائر اللي فيها كابيستر واندكتر وعناصر أخرى ( مثل السويتش والرزيستر وغيرها)\nشابتر 9: الدوائر اللي يكون الكرنت أو الفولتج سورس يتمثل بسانسوديال فنكشن وكيفية تحليلها ، شابتر سهل وممتع.\n\nالكتاب المستخدم للمقرر\nممتاز جدا ويحتوي على أمثلة كثيرة .\n\nمدى فائدته في الناحية التطبيقية\nمهم جدا وأساسي لطلاب الالكتريك .\n\nإضافات:\n- طلاب الاندستريال يكرهوا دا الكورس كثيرا .\n- حاول تحل أكبر قدر ممكن من الأسئلة .\n- ميجر 1 سهل جدا وممكن تجيب فيه درجة عالية بشوية جهد.\n- أغلب دكاترة المادة في فصل 141 كانوا سفاحين في التصحيح .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-201-electric-circuits-i/120694/27", "user": "magbool", "ts": 1421870894000, "tid": 120694, "pn": 27}}', 1421870894000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1483212-ee201', 'stk-red_black', 'EE 201', 'info', '{"desc": "اعذروني على قسوة الكلام، لكن من يقول عن هذه المادة “سهلة” يكذب على نفسه و على غيره. إلا أن يكون من القلة العباقرة فهذا شيء آخر! مادة بصراحة لا ترحم مثقال ذرة. إما أن تملأ دفتراً تلو دفتر بحلك للأسئلة و تمخر عباب الإنترنت باحثاً عن حلول أسئلة يأتونك بها “من تحت الأرض” لم تر مثلها لا في شرح الدرس و لا في شرح الكتاب، و إما أن “تنزف” منك الدرجات كما ينزف الدم من الذبيحة!", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-201-electric-circuits-i/120694/32", "user": "Red_Black", "ts": 1510351716000, "tid": 120694, "pn": 32}}', 1510351716000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1485325-ee201', 'stk-abdullah2015', 'EE 201', 'info', '{"desc": "أخذت الكورس في ترم 171 مع الدكتور سليم ابرير.\n\nجودة المقرر بشكل عام:\nممتازة.\n\nالمواضيع التي يغطيها المقرر:\nغطوها الأخوة اللي قبلي فما فيه شيء أزيده…\n\nزبدة الكلام إن الكورس يتكلم عن طرق تحليل الدوائر الكهربائية بشكل عام، يعني كيف توجد الكرنت والفولتاج في كل فرع في الدائرة الكهربائية.\nما فيه شيء تطبيقي عملي في هذا الكورس، لأنه كله طرق تحليل وحسابات.\n\nالكتاب المستخدم للمقرر:\nhttps://www.gulf-up.com/12-2017/1514741044451.jpg\n\nالأسئلة والأمثلة المستخدمة في المقرر:\nالكتاب فيه عدد كبير جدًا من الأسئلة، لكنه لا يغني عن الأولد إقزام، يعني أكيد الكتاب مفيد جدًا في ترسيخ المفهوم، لكن للمذاكرة للاختبارات ما يكفي، لأن في اختباراتهم يركزون على أشياء أسئلة الكتاب ما تركز عليها.\n\nمدى فائدته في الناحية التطبيقية:\nكورس تحليل الدوائر الكهربائية يعتبر اللبنة الأساسية لكثير من مواد التخصص، فلازم تفهم هذا الكورس بشكل كويس جدًا لو كنت طالب هندسة كهربائية، أما إذا كنت من طلاب الهندسة الصناعية أو أحد التخصصات الثانية فراح يعطيك فكرة عن الدوائر الكهربائية بشكل عام.\n\nإضافات:\n- فيه شباب يقولون إن الكورس سهل، فعلًا أنا الآن خلصت الكورس وأشوف المواضيع اللي فيه سهلة، لكن في بداية السمستر ما كنت أشوفها كذا، ففي البداية طبيعي إذا حسيت إنك ضايع ومش عارف من وين تبدأ في تحليل الدوائر، لكن ما هي إلا مسألة وقت حتى تتعود.\n- الهومووركات مهمة جدًا في هذا الكورس، إذا فهمت الهومووركات إن شاء الله أمورك تمام، فحاول إنك تحلها بنفسك، أو إذا نقلت تنقل بفهم.\n- هذه القناة فادتني كثيرًا، وتمنيت إني عرفت عن وجودها في بداية السمستر، لكن للأسف ما دريت عنها إلا قبل الفاينل بثلاثة أيام:\nFundamentals of electric circuits\nعمومًا النت مليء بالشروحات للمنهج، لكن اللي يميز هذه القناة إنه ماشي على تسلسل الكتاب وشرحه واضح وبالعربي.\n\nبالتوفيق للجميع 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-201-electric-circuits-i/120694/34", "user": "Abdullah2015", "ts": 1514740771000, "tid": 120694, "pn": 34}}', 1514740771000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1492316-ee201', 'stk-breaktheunbreakable', 'EE 201', 'info', '{"desc": "المادة تحتاج حل أسئلة ومتابعة وشغل. القسم غريب، يحط لك أسئلة صعبة والوقت قصير والتصحيح سيئ. المهم يبيلك تنتبه لأن الدرجات تطير بالسهولة، فالك الدرجات العالية.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-201-electric-circuits-i/120694/37", "user": "BreakTheUnbreakable", "ts": 1526273751000, "tid": 120694, "pn": 37}}', 1526273751000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1518603-ee201', 'stk-mr.power', 'EE 201', 'info', '{"desc": "بسم الله الرحمن الرحيم …\n\nالمادة حقيقة هي بس أول ٤ شباتر ، بعد ذلك تصبح مادة عقل حقيقة …\n\nأعني بذلك ، أول أربع شباتر هي الأساس ، يعني الكوخ عشان ينبني يحتاج أربع أعمدة ، لو عمود واحد أنكسر ، طاح الكوخ بأكمله ، فالمقصد هنا الطرق والكونسبت حقت أول أربع شباتر هي الأعمدة للكورس ، وبقية الشباتر هي التضبيطات اللي داخل الكوخ .\n\nيعني كل اللي تحتاجه عشان تفهم وتحل مسائل شابتر ٦ و٧ و٨ و٩ ، هو كونسبت وطرق أول أربع شباتر .\n\n-\n\nالمادة ليست صعبة وبل بالعكس سهل جداً الحصول فيها على قريد عالي وعالي جداً كذلك ، ولكن هالشيء ماراح يجي بس بالمذاكرة وفهم الكونسبت ، لا لا ، أنا كمثال ، دخلت الميجرين والفاينلات ، وكلهم كنت فاهم الكونسبت ١٠٠٪؜ ، وكذلك بالميجر الأول والثاني حليت أولد اقزام ، ومع ذلك درجاتي جداً عادية وكنت أواجه صعوبة عالية في اسئلة الاختبارات .\n\nبشكل عام ، المادة صعوبتها مو بالكونسبت وطرق الحل ، المادة جداً سهلة من ناحية الكونسبت ومن ناحية الحل ، لانه الماث اللي فيها جداً بسيط وأشياء أساسية ، على قولتهم سمبل ماث ، ولكن الاشكالية في الاختبارات ، مهما حليت أولد اقزام وكنت فاهم الكونسبت ١٠٠٪؜ ، المراهنة أنك تبدع بالاختبار صعبة جداً ، لانه الاسئلة اللي تجي تكون مختلفة عن أفكار الاولد اقزام ، وهالشيء بسبب أن السيركت فيها أفكار كثيرة ولعب كثير يعني اللعب والخدع جداً كبير .\n\nكملخص ، اختبارات المادة ماتحتاج منك أنك تكون فاهم الكونسبت وحال اولد اقزام والواجب ، لا ، تحتاج منك بالاضافة إلى هالاشياء ، أنك تشغل مخك ، يعني بالبداية لمن تشوف السيركت تفكر فيها بمخك أولاً ، وبعدين الخطوة الثانية هو استخدامك للكونسبت حق المادة .\n\nيعني كل سؤال بالاختبار يكون تسلسله هكذا …\n\nالعقل والتفكير السريع - استخدام الكونسبت - حسابات وسمبل ماث - الجواب .\n\nوفقكم الله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-201-electric-circuits-i/120694/38", "user": "Mr.power", "ts": 1577893001000, "tid": 120694, "pn": 38}}', 1577893001000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1524047-ee201', 'stk-user11942', 'EE 201', 'info', '{"desc": "المادة ككونسبت سهلة والماث الي تعتمد عليه سمبل، لكن التطبيقات وأسئلة القسم فيها صعوبة وتعقيد، بالإضافة إلى أن الوقت لا يتناسب مع طبيعة الأسئلة؛ فلازم تطور مهارة الحل السريع. الكورس هذا يحتاج شغل وأمثلة الكتاب ممتازة.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-201-electric-circuits-i/120694/39", "user": "user11942", "ts": 1595250345000, "tid": 120694, "pn": 39}}', 1595250345000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1526516-ee201', 'stk-user11724', 'EE 201', 'info', '{"desc": "EE202-Term201\n\nالمادة يحتاج لها تدريب كثيف خصوصا في البداية عشان تفهم كيف تحلل الدوائر المعقدة بعدين، وفي نفس الوقت تصير واثق في نفسك، ممكن شيء بسيط يتغير في الدائرة الكهربائية وحلها يتغير فيحتاج تفكر بمنطق وايش اسهل طريقة حل ممكن تحل فيه، اخذتها في الاونلاين ووضعها كويس غير انها تفتح مواد كثيرة فلازم تاخذها، ذحين رجعوا تسيميتها القديمة في الخطة الجديدة وصار اسمها EE201، عموما طلاب باخشوين مضغوطين اكثر ولكن افرجهم اعلى في الميجر.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-201-electric-circuits-i/120694/40", "user": "user11724", "ts": 1604555311000, "tid": 120694, "pn": 40}}', 1604555311000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p115071-ee201', 'stk-imported_mr_industri', 'EE 201', 'info', '{"desc": "ااسلام عايكم…\n\nنصيحة في EE201\n\nأنا أخذتها مع الدكتور الزاهر.053\n\nالمادة سهلة و ما فيها شيء\n\nلا تهملها\n\nلأن الفاينال صعععععععععععععععععععععععععععععببببببب\n\nأول بأول نصيحة\n\nأنا قبل الفاينال 61 من 70 القريد كان c+ تخيل\n\nأنصحك لا تهملها و أعطيها مجهود و أضمن اللاب لأنه سهههههههههههههههههل\n\nوااله الموفق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-201/52012/6", "user": "imported_Mr_Industri", "ts": 1157633955000, "tid": 52012, "pn": 6}}', 1157633955000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p979240-ee201', 'stk-user8409', 'EE 201', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nالسلام عليكم … 🌹\n\nيعلم الله انني لم افكر بانزال هذا الموضوع الا لحصر الافكار ووالمسائل التي تواجه جميع دارسي المادة\n\nفقد تمر مسالة على طالب وتكون صعبة ومعقدة ولا تمر علي او على شخص آخر وقد تكون النتيجة سلبية في الاختبار لا فات الفوت ماينفع الصوت ]\n\n🌹\n\nهنا مجموعة من الملفات التي انصحكم بجعلها ركيزتك ومصا]درك لهذه المادة\n\nوايضا روابط لمواقع جدا جميلة\n\nاولد اكزامز ميجر ون وتو للأترام 081-082-092 ] + فاينال 092]\n\nZERGUINE’S SLIDES\n\nبرنامج ملتزم\n\nThe Book of electric circuits 9TH\n\nThe solutions Manual\n\nموقع يعطيك اسالة وتجاوب عليها اون لاين\n\nالموقع هنا\n\nللدخول على الاسالة الاون لاين ناظر الـ name الذي ينتهي ب html\n\nصورة للموقع\n\nhttp://www.m5zn.com/uploads2/2012/2/3/photo/020312090253l5itdlev9epue5yspfvve6qnh.png\n\nصورة للاسالة الاون لاين\n\nhttp://www.m5zn.com/uploads2/2012/2/3/photo/020312090253tpwkpexpzsnds.png\n\nاذا اردت مثال مشابه للسؤال الاون لايني هناك ملف بي دي اف باسم worked Examples\n\nاي واحد عنده سؤؤؤال بالهوم ورك او اولد اكزام ما ياليت انه يطرحه هنا\n\n+\n\nالي عنده اولد اكزامز للاترام 101 + 102 + 111\n\nالله لا يهينه يضعها هنــا\n\nيظن البعض ان مسألة الحصول على A+ تطلب 95 فأعلى\n\nاؤكد لكم ان 99.9 لا تكفي لتضمنها", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee201/119713/1", "user": "user8409", "ts": 1328293818000, "tid": 119713, "pn": 1}}', 1328293818000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p75755-ee201', 'stk-user889', 'EE 201', 'info', '{"desc": "انا منزل الترم هذا عن الدكتور حسين مسعودي(( MASOUDI H ))\n\nوصراحة الدكتور مرررة اخلاق وشرح وكل شي …\n\nبس في مشكلة وحدة بس …\n\nان المياجر عنده مرررة سهله جدا بالذات الميجر الاول كان تافه فاذكر ان الطلاب خرجوا من الميجر يسبون فيه…\n\nوالسبب ان الميجر تاافه جدا والطلاب زي ما تعرف جاهزين للصعب …\n\nواما الميجر التاني كان شوية صعب بس تقدر تقول ان الطلاب ماكانوا مستعدين …\n\nباختصار والله انه حبيب وانصحك تنزل عنده\n\nاسف على التاخير بس يمديك تلحق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee201/47756/9", "user": "user889", "ts": 1116201022000, "tid": 47756, "pn": 9}}', 1116201022000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p438830-ee201', 'stk-user3490', 'EE 201', 'info', '{"desc": "من باب الحيادية\n\nكل مدرس لو طريقتو في الشرح\n\nفهو أصلا ما يقدر يسوي أكثر من كذا وهذه قدراتو\n\nأنا شخصيا لا أحب طريقة القراءة من السلايدات بدون فهم لأنها لا تعلم شيئا\n\nلكن أحيانا في من يكتب نوت لكن لا يستطيع أن يفهم الطلاب ما كتبه\nأو أنه يكتب رؤوس أقلام ويتكلم قليلا ويقول شرحت\n\nالشرح يا ناس مهارة للأسف ما يستطيعها إلا الذي يطور نفسه فيها\n\nأنا أذكر الدكتور شيخ شريف كان يشرح على سلايدات لكنو يحرص انو الطالب يطلع فاهم\nوالله كلاساتو كانت من احسن الكلاسات عندي في 390\n\nعشان كذا يا طالب اذا ما عجبتك طريقة مدرس في الشرح ببساطة لا تاخذ معاه\nواذا اضطريت لازم تعتمد على نفسك تقرأ نوت دكاترة ثانيين أو تحضر مستمع عند دكتور يدرس نفس المادة\n\nةعلى فكرة الاونلاين لكتشر لمادة ee201 جدا ممتاز وأعتقد يغنيك عن شرح الدكتور\n\nبس مواد مثل 200 و203 و380 وأي مادة تحتاج شرح مدرس ما ينفع معاها الونلاين ليكتشر", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee201/76051/3", "user": "user3490", "ts": 1248948713000, "tid": 76051, "pn": 3}}', 1248948713000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p246799-ee201', 'stk-barca', 'EE 201', 'info', '{"desc": "السلام عليكم …\n\nاخواني انا طالب عند الدكتور بالغنيم ee201 … الدكتور يقول ذاكر من الكتاب منب منزل السلايدات على الويب … وبما اني coe فمااتوقع اني ابسويها  …\nاللي اسأله فيه احد عند سلايدات الغنيم ماخذها قبل … ولا اي دكتور ثاني بما ان الاختبار كومون …\n\nشكرا للجميع …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee201/61714/1", "user": "barca", "ts": 1203843609000, "tid": 61714, "pn": 1}}', 1203843609000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p246817-ee201', 'stk-user3653', 'EE 201', 'info', '{"desc": "اخوي انا ماخذ الماده من قبل … الماده مو صعبه كثير بس زي اي ماده اليكتريك يبي لها متابعه وحل امثله لا اكثر\n\nبالنسبه للكتاب تراه حلو للمعلوميه انا ماني دافور -.-\" بس الكتاب وامثلته مقبوله ولو تحل الاساله الللي بلون مختلف ترى تساعدك (على انها صعبه نوعا ما … بس مو كلها )\n\nطريقتي كانت اني انتبه للشرح و استعمل الاون لاين لكشر تراها حلوووووووووه كثير وتفهمك واغلب الشباب كان يذاكر منها\n\nوبعدين حل لك كم مثال في الكتاب و الهوم وورك وكان الله غفورا رحيما", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee201/61714/2", "user": "user3653", "ts": 1203847708000, "tid": 61714, "pn": 2}}', 1203847708000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p77454-ee201', 'stk-the_maestro', 'EE 201', 'info', '{"desc": "اخي الكريم\n\nانا طالب EE اتخرج انشالله بالصيف هذا\n\nو انا و لله الحمد و المنة اني اكملت كل كورسات ال EE\n\nفمن خلال خبرتي اقول لك … ان كورس EE 201 كورس مهم مهم مهم مهم مهم جدا جدا جدا جدا جدا\n\nاذا تبغى تفهم تخصصك و تعديه باعلى معدل ممكن هو انك تهتم و تركز على هذا الكورس … و الله العظيم هذا الكورس راح تطالب بمفاهيمه الى اخر نفس في كورسات ال EE … و لما توصل انشالله الى كورسات ال SENIOR راح تذكر كلامي و تشوف انه نسبة 98% من كورسات ال EE تطالبك بمفاهيم EE 201\n\nو على هذا فأنا اقول لك لا تضيع على نفسك فرصة دراسة هذا الكورس عند مدرس من العيار الممتاز و ان تدرسه في ظروف طبيعية يعني انا من وجهة نظري انك طالما معدلك نازل شوي , فاذاً انت لست من الدوافير … فأنا انصحك انك تدرس هذا الكورس المهم في سمستر مو في صيف حتى يتسنى لك ان تهضمه بالراحة مو بالعجلة …\n\nلانه من جد كورس مهم …\n\nاما بالنسبة “للساعاتي” فاللي اعرفه عنه انه مو افضل من غيره … هناك دكاترة بالقسم افضل منه بكثير …ز\n\nنصيحة اخيرة … بالذات في كورس EE 201 لا تبحث عن الوقت المناسب للمحاضرة و لا عن الدكتور اللي يعطيك قريد بل ابحث عن الدكتور اللي يفهمك صح …حتى لو طلعت من الكورس ب C و انت فاهمه مضبوط …احسن من A وانت ماتدري بالسالفة\n\nلانه مثل ما قلت لك …اذا اخذت فيه C بس بسبب ان الدكتور صعب في القريد بس انت فاهم المادة صح … فأنا اقول لك ما راح تاخذ اقل من B في كورسات ال EE\n\nهذا و امنياتي لك بالتوفيق و النجاح\n\nاخوك\nالمايسترو", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-201/48116/2", "user": "The_Maestro", "ts": 1119097605000, "tid": 48116, "pn": 2}}', 1119097605000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p77571-ee201', 'stk-user564', 'EE 201', 'info', '{"desc": "أسير الصمت نزل عند بالترتيب\nالجامد\nأو العبسي\nعصام حسن…\n\nشكوور اخوي,عاد تصدق واحد قالي نزل عند الحسن,هذا نمبر ون,\nبس بما ان تخصصك كهرابئيه,شكلك أعرف,يعطيك العافيه\n\nThe Maestro هذا الكورس مههههههههههههههههههههههههههههههههم\n\nجدا جدا لطلاب ال EE\n\nو بما انك طالب SE فأنا أقول لك اسأل طلاب ال SENIOR SE\n\nاذا هذا الكورس تحتاجوه في مواطن حرجة في كورسات اخرى في تخصصكم فأانا أنصحك انك تاخذه مع دكتور يشرحه بشكل ممتاز\n\nو اما اذا كان كورش هامشي بالنسبة لكم …فأقول لك خذه مع دكتور يعطيك قريد …و انا اعتقد ان الجامد واحد من هالدكاترة …مع العلم انه دكتور ممتاز جدا في الشرح بعد\n\nاخوك\n\nالمايسترو\n\nاخوي المايسترو,مشكور على نصاايحك\n\nوالله اخوي,بما ان مافيه الا هالكورس أو هالماده الي تتعلق بالكهربائيه,شكله ماله ذاك الاهميه ,\nوشكلي زي ماقالت انت واخوي اسير الصمت,أنزله عند الجامد\n\nويعطيكم ألف ألف عافيه,", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee201/48136/4", "user": "user564", "ts": 1119611002000, "tid": 48136, "pn": 4}}', 1119611002000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p95887-ee201', 'stk-user1574', 'EE 201', 'info', '{"desc": "السلام عليكم\nبالنسبة للي ذكرتهم\n\nالدريش هو أصلا حق 207 مو 201 بس شرحه ممتاز وأسئلته حريقة وقريده غير منصف البعض يمدحه والبعض يذمه@62@\n\nالساعاتي وعبدالجواد إذا أنت تخصصك مو Ee أنصحك بهم لأنهم شرح ماعندك أحد بس قريدات طيبة وخصوصا عبدالجواد إذا كنت من أهل جدة أبشر بقريد@14@\n\nالجامد معلم المادة هذه وغالبا هو الكوردنيتر شرح أكثر من رائع وقريده عادي الأغلب عنده C@4@\n\nحبيب الله شرح توب بس من زمان مادرسها أسئلته نار قريده لا بأس@37@\n\nراغب عسل ومتساهل وأفرجه عالي وقريده واطي شرحه متوسط@14@\n\nملاحظة لكل طلاب الهندسة الكهربائية المستجدين@24@\n( ضحي بالقريد من أجل فهم الee 201)\nعشان كذا أرشح\nالجامد ثم\nحبيب الله ثم\nالدريش ثم\nراغب\n\nسامحني بس اللي صعب التقييم أنه أغلبهم من زمان مادرسوا ال201\n\nأما اللاب فخذ على الوقت\nماعدا بالغنيم أو زيدوري أو الساعاتي أذا أمكن تتجنبهم لأنهم دكاترة وبيتفلسفو ع راسك بزيادة@37@\nيازين أبو هنود@14@\n\nأتمنى أكون قد أفدتك\nوشكرا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee201/50312/5", "user": "user1574", "ts": 1145833799000, "tid": 50312, "pn": 5}}', 1145833799000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p441227-ee201', 'stk-husain_ee', 'EE 201', 'info', '{"desc": "أنا ما أعرف حقيقة هل الكلام الي اقراه الآن كلام طلاب جامعيين أو لا؟!\nو هل هذا أصلاً كلام يليق بطلاب جامعة الملك فهد أو لا!؟\nأنا ما أعرف بالضبط شنو تبون من الدكتور؟! العلامات أو الأخلاق أو الشرح أو شنو؟!\nلأنه أول شي مافيه شخص كامل و الكمال لله سبحانه و تعالى\nشيء ثاني كل دكتور راح تحطون فيه ألف عيب!!!!!\nعلى العموم إذا طريقة السلايدات ما تعجبكم فأنصحكم تغيروا الجامعة من الآن!!\nلأنه الآن أكبر الجامعات الأمريكية تعتمد على طريقة العرض و السلايدات\nو غير كذا و الأهم … في الحياة العملية كل الوضع راح يكون سلايدات × سلايدات\nأنتم بكرة مهندسين و تعرفون المفروض إنه لازم تآخذ ملاحظاتك و تسجلها\nو بعدين إذا فيه شي مو واضح تقدر تخلي المحاضر (سواء دكتور أو مهندس آخر يقوم بالشرح) بالإجابة على الاستفسارات\nو لكن للأسف … نعم للأسف و هذا سبب من أسباب كلام الكثير إنه خريجي البترول الآن ليسوا في جودة السابقين\nللأسف الطلاب و الجيل الحالي بدأ يعتمد على الملخصات و النوتات فقط … فقط … فقط\nو نسوا المصدر الأساسي و الصحيح و السليم للمعلومة … الدكتور المدرس للمادة\nالدكتور المدرس للمادة هو مدرس خصوصي و ببلاش تقدر تجيه أي وقت و تسأله عن شي يصعب عليك\nو أزيدك … هذا الدكتور هو الي يعلمك المادة و راح يجيب لك اسألة الإختبار و راح يحط علاماتك\nفكيف غريب إنك ما تجي له المكتب و تسأله الأسئلة؟! هذا يدل على أمر من أمرين:\nالأول: إنه كل شي واضح و كل النقاط مفهومة و ما فيه داعي تجي تسأل الدكتور؟!\nالثاني: إنه مو فاهم شي و لا عارف شنو صاير في المنهج!!\n\nقبل لا أحد يجي يتهجم على أي دكتور لازم يكون عنده أدلة و براهين و حجج واقعية\nفشل الشخص في الجامعة لا يجي يعلقه على غيره … الدكاترة هنا قمة و واجهة المملكة في التعليم!\n\nأتمنى أن تعيد الجامعة التفكير مرة أخرى في نظام القبول الحالي … الجامعة أصبحت صيد سهل للجميع\nالله يرحم أيام زمااان لما ينحلف براس الجامعة و كيف إنه صعب القبول فيه … الآن كل من هب و دب يقبل فيها\nأتمنى إنه كلامي عن القبول و اختبارات القبول يأخذ بشكل جدي لأنه مو مهم نخرج مهندسين بقدر ماهو مهم تخريج مهندسين أكفاء … يملكون المؤهلات للتكيف و التأقلم مع جميع الظروف", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee201/76051/7", "user": "Husain_EE", "ts": 1249303022000, "tid": 76051, "pn": 7}}', 1249303022000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p441510-ee201', 'stk-user5258', 'EE 201', 'info', '{"desc": "أشكرك أخي المتهندم على حياديتك 🙂\nذكرت في ردك بأن كل مدرس له طريقة معينة في الشرح…فأنا أوفقك مئة بالمئة بناءا على قدارته.\nلكن يا عزيزي ألا تعتقد بأن الضحية الأولى هو الطالب؟\nالطالب يبحث عن فهم المادة وعن تطبيقاتها وخاصة اذا كان طالب ee وبدون ما نضحك على بعض الطلاب ايضا يهمه معدله ونتيجته في نهاية الكورس.\n\nبالنسبة لقضية القراءة من السلايدات فالكثير لا يحبذ هذه الطريقة وأنا منهم.لكن من المفترض اذا كانت طريقة الدكتور بأن يقرأ عن طريق السلايد فليوكلني هذه المهمة.\nبعض الشرح يفيد الطالب ولن يضره 🙂\n\nوقضية أن الطالب له الحرية في إختيار الدكتور المناسب فأنا أؤكد لك بأن أسماء المدرسين لم تنزل الا بعد إنقضاء الإسبوع الأول… فأين حرية الطالب في الإختيار ؟\n\nوهنا أقول أني لن أعطي مادة أكثر من إنها تحتاج على حساب المواد الاخرى فالبعض لن يستطيع الحضور لمدرس أخر 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee201/76051/8", "user": "user5258", "ts": 1249325591000, "tid": 76051, "pn": 8}}', 1249325591000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p498682-ee201', 'stk-user1551', 'EE 201', 'info', '{"desc": "السلام عليكم\n\nحيالله طلاب الجامعة الغالية\n\nأنا أخذت الكورس مع الدكتور سمير ترم 61 والحمد لله طلعت معه ب a+\n\nأنا لن أتكلم عن شرح الدكتور ولا عن المادة ( لأن المادة وبكل صراحة سهلة للغاية إذا حاولت تفهم السلايدات وتتطبق في أسئلة اخر الكتاب وأعتقد أن حلول الكتاب متوفرة في الشير )\n\nأنا سأتكلم عن أخلاق الدكتور وتعاونه مع الطلاب\n\nالدكتور سمير من أفضل أو أفضل الدكاتره من ناحية الأخلاق والتواضع للطلاب\n\nأما تعاونه فحدث ولا حرج, أنا تواصلت معه بعد ما أنهيت الكورس وكنت أجيه في أكثر الأحيان لكي أخذ من النصح\nفي بعض المواد\n\nبل تخيلو أنه أعطاني أكثر من مرجع في 207 والمات لاب و dsp وما رجعتها إلا بعد التخرج\n\nمن وجهت نظري أن الطلاب تعودو على التذمر وإلا فالمادة سهلة ولا تحتاج دكتور", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee201/76051/14", "user": "user1551", "ts": 1260171177000, "tid": 76051, "pn": 14}}', 1260171177000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p78394-ee201', 'stk-user1091', 'EE 201', 'info', '{"desc": "أحسن واحد يقولون هو الجامد وأكثر الشباب يمدحونه\n\nوبعدين عندك عصام حسن\n\nوهذا بعض الكلام عنه من شباب المنتدى\n\nعصام حسن : (201)\n\nرجل فاهم المادة 100% … شرحه مرتب و نوت و لا احلى … لو يألف كتاب من النوت حقه … اتوقع يكون اصرف و افضل للطلاب من الكتاب اللي يدرسونه حاليا … مع اعجابي في طريقة الكتاب … لكن نوت عصام حسن جدا ممتاز …\nمعاملته ادنى من المتوسطة بقليل … فيه روح من المساعدة في شرح الغير مفهوم…\nمن ناحية الاختبارات … لازم تلقى لك سؤال فيه تريك (trick) بس بشكل عام أسئلته معقولة\nمن ناحية الدرجات …\n\nوبالنسبة للمسعودي\n\nد. المسعودي (حسين): والله هذا الدكتور قمة في الشرح ونوتاته ولا أحلى بس ينخاف من قريداته -ما يعطي قريدات عالية-", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-201/48262/2", "user": "user1091", "ts": 1122560618000, "tid": 48262, "pn": 2}}', 1122560618000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p78605-ee201', 'stk-u_n', 'EE 201', 'info', '{"desc": "هذا اللي اعرفه عنه\n\nالاخ العزيز\n\nالسلام عليكم\n\nفما يخص مادة EE 201 مع د المسعودي اليك معلومات اللي درسوا عنده الفصل 042\n\nاختباراته\n\nمثله مثل كل الدكاتره\n\nmajor 1 15%\n\nmajor 2 15%\n\nاللي يميزه عند الدكاتره التانين ان الاختبار عنده في الكلاس تايم في نفس الكلاس 50 الى 55 دقيقة\n\nثلاثة أسئلة فقط عادة ما تكون سهلة خاصة major 1\n\nQuizzes\n\nالرجال يعطي كل اسبوعين كويز بانتظام يعني ما يتغيرعن موعد الكويزات الا نادر\nكل كويز عليه 2% يعني الموجموع 10 %\n\nلو ايش ما يزود ولو كويز واحد خمسه يعني خمسه\nمو عد كويزاته كل اربعاء\n\nباقي اقول ان المنهج (الماتيريل ) حق الكويز هو الماتيريل اللي غطى حتى الاربعاء\n\nيعني اذا فيه كويز الاسبوع الجاي الماتيريل حقه هو الماتيريل اللي غطى حتى نهاية الاسبوع اللي قبل اسبوع الكويز\n\nفهمت عليه !!\n\nassigments\n\nالرجال يعطي خمس هومركات من عنده تعملها ب Multsim مثل االبيس بايس\nعلى كل اسايمنت 1 % يعني المجموع خمس في المية\n\nلما تجمعها مع الكويزات يصير المجموع 15 في المية وهذا هو الكلاس وووورك\n\nبالاضافة الى 30 % مياجر هذي 45 في المية\n\nاللاب 20 في المية هذي 65 في المية\n\nوالفاينل طبعا 35 في المية واللي صار موحد مع كل الشعب التانية\n\nانا اعتبر شرحه تمام وفاهم مره ومجتهد\n\nيمكن يعتبر من احسن ثلاثثه دكاتره في القسم اللي يدؤسو الماده هذي\nوالله اعلم\n\nفيما يخص القريد وهذا اهم شي عند اغلب الطلاب انا اعتبره مره شديد في القريد مره\n\nاللي تجمع يعطيك من غير زياده ولا نقصان ولا تعاطف\n\nوالله اعلم\n\nاتمنى اني وفيت اللي وصلني عن الدكتور هذا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-201/48262/5", "user": "U_N", "ts": 1123148251000, "tid": 48262, "pn": 5}}', 1123148251000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p845360-ee201', 'stk-user4571', 'EE 201', 'info', '{"desc": "الاون لاين لكتشرز مش بطالة وفادت ناس كثيرين بالفاينل\nالمادة ما يبغالها الا شي واحد\nحل قد ما تقدر من المسائل يعني مسائل الهووم وورك مثل ما قالكProf.EE وشوف مسائل الفاينل ودور عليها بالكتاب او شف مشابه لها وحلها\nاهم شي حل مسائل عشان اذا جا الامتحان وغيرو شي الا انت تقدر تتصرف خصوصا انك ع قولتك مضيع\nوفالك التوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee201/107665/3", "user": "user4571", "ts": 1306898353000, "tid": 107665, "pn": 3}}', 1306898353000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p845954-ee201', 'stk-user6410', 'EE 201', 'info', '{"desc": "أسأل الله لكم التوفيق والسداد\n\nكتاب مادة 201 هو أفضل طريقة للمذاكرة\nكتاب واضح و منظم بشكل جميل\nأنصح بأن تقرأة وستجد الفائدة\n\nوكذلك 205 تراجع من نفس الكتاب\n\nوأنصحك في النهائي بأن تركز على طرق جمع/طرح و ضرب/قسمة الأعداد التخيلية (complex NO.)\nلأنها هي الشيء الوحيد الجديد في النهائي\n\nحاول أن تحل الإختبارات القديمة وإن شاء الله تجد خير.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee201/107665/6", "user": "user6410", "ts": 1307067047000, "tid": 107665, "pn": 6}}', 1307067047000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p959206-ee201', 'stk-m_o_h_a_m_e_d', 'EE 201', 'info', '{"desc": ".\n.\n\nوعليكم السلام ورحمة الله وبركاته\n\nشباب عندي استفسار بخصوص توزيع الدرجات في الـee201 يعني الفاينال والكويزات والبروجكت كم عليهم ؟؟\n\nميجر 1 = 15 %\n\nميجر 2 = 15 %\n\nكويزات = 15 %\n\nهومووركات = 5%\n\nالفاينل = 30 %\n\nاللاب = 20 %\n\nالمجموع = 100 %\n\nأما البروجكت أعتقد شالو 5 % من الكويزات وحطوها للبروجكت\n\nهذا الي أعرفه والباقي ماعندي علم للأسف\n\nبالتوفيق 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/questions-about-ee201-final-exam/117511/2", "user": "M_O_H_A_M_E_D", "ts": 1325708492000, "tid": 117511, "pn": 2}}', 1325708492000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p893450-ee201', 'stk-user6860', 'EE 201', 'info', '{"desc": "ee 200 & ee 201\n\nحجري الأساس للهندسة الكهربائية وخصوصا ee 201… أسهل كورسين كهرب…\n\nee 200 الكورس بسيط وسهل يتكلم عن اللوجك وانظمة الأرقام وكلام بسيط جداااااااااا… في نهايته يكون متوسط المستوى ويحتاج له جهد موب سهل… الأفرج عالي في هالكورس…\n\nee 201 الكورس بسيط وسهل ويحتاج له كرف وحل اسئلة لانه هو تحليل الدوائر الكهربائية ومافيه نظريات ولكن كلما حليت دوائر اكثر راح يكون ابداعك اكبر في المياجر، الكورس اساسي جدا علشان تمشي امورك في التخصص،حاول تفهم قد ما تقدر ولايهمك القريد خصوصا هالكورس أهم شي: الفهم!!!!!!!! لأنه هو راح يشكل قوتك في التخصص وخصوصاً كورسات ee 203 , ee 205, ee 360 ee 303 و بعض الأساسيات في كورسات مختلفة، الكورس القريد فيه موب صعب", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee201-ee-200/111265/5", "user": "user6860", "ts": 1314660367000, "tid": 111265, "pn": 5}}', 1314660367000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p894784-ee201', 'stk-user5671', 'EE 201', 'info', '{"desc": "٢٠٠ بالنسبه لي هذا اللي سويته\nكنت اتابع مع المدرس اول باول في سلايداته بس\nوانصحك تشوفها سلايدات الشعراوي\nوكانت هي مصدري الاساسي ولا اتذكر اني رجعت لاي شي ثاني والحمد لله طلعت بقريد حلو\n\nاما ٢٠١ فنصحك وبقوه بقراية الكتاب وبقوه\nوحل اسئلته هي كانت مصدري الاول والاخير واظمن لك الـa+\nومهما كنت تعتقد نفسك فاهم انصحك تتاكد بحل اسئله قدر الامكان\nلان افكار هالماده ماتنتهي ، مع انها سهله لكن يبغالها براكتس\nوالسليوشن مانويل موجود في التراكر\n*", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee201-ee-200/111265/7", "user": "user5671", "ts": 1315166907000, "tid": 111265, "pn": 7}}', 1315166907000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1535262-ee201', 'stk-ria', 'EE 201', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\n\nردي متأخر لكن ان شاء الله يفيد الطلاب اللي بيجون بعدي طرق المذاكرة لهذا المقرر والحصول على +A بالدعاء لله بالتوفيق والنجاح ثم التمرين بالكتاب وحل على الاقل 3 اولد اقزامز كاملة وفيه فيديوهات كثيره تبسط المادة تغنيك عن الدكتور مثل:\nالمهندس كريم:\nhttps://www.youtube.com/playlist?list=PLFM6wDAJoh--qm9UD3VatCBeGJaPGlLK6\nوشرح طالبة كويتية:\nhttps://www.youtube.com/playlist?list=PLVVYNLhxBzoorzsO-eRrgYwzI_CkVx8wp\n\nالكورس سهل فا لا تضيع فرصة الـــ+A وخصوصا انه اول ميجر اسهل ميجر كلها اشياء بسيطة ولو ما ذاكرتها زين بتنغصب تفهمه عدل لانه الكورس كامل مترابط\n\nاسأل الله لكم التوفيق ودعواتكم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee201/119657/5", "user": "RIA", "ts": 1662055459000, "tid": 119657, "pn": 5}}', 1662055459000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p778470-ee201', 'stk-user4870', 'EE 201', 'info', '{"desc": "عموما مواد الصيف يكون المنهج فيها اقل لكن مو بذيك الدرجة\nلكن تذكر انك بتصير مكروف في الصيف ولازم مذاكرة اول باول لانه في الاسبوع الثالث يجيك ميجر ون ثم في الخامس او السادس يجيك الثاني بعدين بعد الثامن يجيك الفاينل !\nاذا انت بتشد حيلك فتراها حلوة خاصة انه يصير عندك في الترم اللي بعده 203 و205 و207 مفتوحة ! وانت بتاخذ 200 الترم الجاي ,اذا انك 29 فعال العال ما شاء الله ويمكن تتخرج في 4 ونص اذا اخذت كل الاصياف . اما اذا انت 28 فما انت متأخر واجد بس فصل واحد وتقدر تعوضه باذن الله في الاصياف القادمة .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee201/101768/4", "user": "user4870", "ts": 1296331727000, "tid": 101768, "pn": 4}}', 1296331727000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p688680-ee201', 'stk-fond_of_you', 'EE 201', 'info', '{"desc": "بالنسبة للفاينل صعب تلقى بالنت … غير اللي موجود بالجمعية بس 🙂\n\nلكن اهم شيء بالنسبة للee201 انك تحل اسئلة الهومورك لانهم يوم خذتها\n\n091 سؤالين كانوا بالنص وبالارقام من الهومورك عليهم حدود 20 درجة\n\nوالاسئلة الباقية كانت واضحة مثل الامثلة اللي بالاونلاين كورس … موفق 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee201-final-exams/93829/2", "user": "Fond_Of_You", "ts": 1282535690000, "tid": 93829, "pn": 2}}', 1282535690000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p694969-ee201', 'stk-homesickness', 'EE 201', 'info', '{"desc": "اذا كان عبد الحليم اللي اعرفه / درسني ee204\n\nوالله انه شنب بالدرجات والكلاس ورك\n\nميجر ون تحت الافريج < قريب مو بعيد عنه\nميجر تو فوق الافريج < قريب مو بعيد عنه\nالفاينل احس اني بدعت فيه\nالكوزيز < حوسه\nالهوم ورك < حوستين\n\nطلعني بـ B\n\nأحس اكثر من اللي استحقه\n\nلكن الشهادة لله ،، الشرح من جنبها … يمسك اوراق ويعبي السبورة اكزامبلز اللي موجودة بالكتاب\nلين تخلص المحاضرة\n\nلكن من ناحية الدرجات ذيب …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee201/94274/5", "user": "HOMESICKNESS", "ts": 1283255368000, "tid": 94274, "pn": 5}}', 1283255368000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p694988-ee201', 'stk-hzx_300', 'EE 201', 'info', '{"desc": "عبد الحليم مدرس جديد ما درس الا ثالث كورسات من جا الجامعه 207 و 204 و سبشل توبكز\n\nالمدرس في الشرح مثل ما تفضل الاخ homesickness يعني يعبي السبوره من اوراقه ونفس اللي يعبيه موجود بالكتاب\n\nمدرس طيوب ترى ويتقبل كل شيء, بس بالشرح عيبه, كانت كويزاته اصعب من شرحه ب 207 لكن متعاون وتصحيحه ممتاز والقريد زين", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee201/94274/6", "user": "hzx_300", "ts": 1283258181000, "tid": 94274, "pn": 6}}', 1283258181000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p857246-ee201', 'stk-user5689', 'EE 201', 'info', '{"desc": "شوف ال Ee 201 طوووووووووووووووووووويل جدا\n\nفمسألة إنك تذاكر قبل المياجر هذي انساها :: خاصة اذا كنت تبي قريد حلو\n\nأفضل طريقة برأيي هي إنك تحل أسئلة الهووموورك بوقتها :: طبعا السليوشن موجود\n\nلكن أنصحك ما تفتحه نهائي الا بعد الحل للتأكد فقط …\n\nالهووم وورك بياخذ وقت حوالي ساعتين أو أكثر أسبوعيا :: لكن الماده مهمة وأساسيه :: تستاهل منك جهد وتركيز\n\nوالماده تراكميه أيضا :: بمعنى إن كل درس يتبع اللي قبله ::\n\nمعلومه أخيره :: اذا ما فهمت الدرس من الدكتور فصعب جدا جدا إنك تفهمه لوحدك …\n\nلأن أفكار المادة كثيره وتعتبر جديده عليــك فصعب انك تستنتجها لوحدك\n\nوموفق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee201/108799/2", "user": "user5689", "ts": 1308698574000, "tid": 108799, "pn": 2}}', 1308698574000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p857368-ee201', 'stk-a_hme_d', 'EE 201', 'info', '{"desc": "انا كنت اذاكر من online lectures حقت ee 201 تلقاها في الويب سيتي\nمختصره وشرحها حلو وفيها امثلة محلولة وفي اخر كل section فيه سوال يعطيك بس الفاينل انسر .\n\nانصحك تذاكر منها وتحل من اسئلة الكتاب خصوصا مثل ماقالوا الاخوان ان السيلوشن مانويل موجود .\n\nوبالتوفيق انشاء الله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee201/108799/4", "user": "a_hme_d", "ts": 1308718073000, "tid": 108799, "pn": 4}}', 1308718073000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p814817-ee201', 'stk-user8044', 'EE 201', 'info', '{"desc": "السلام عليكم ورحمة الله …\n\nشكرا لك أخ ( ابو البترول ) عى وضعك للميجر .\n.\nلكن اخوي … انا ماقلت إلاَّ الواقع … لو تبحث في كل صفحات دكاترة القسم ماراح تلقى ميجر بالحل …\nصحيح ان حل الميجر ينزل لطلاب المادة في الويب سيتي … لكن معظم الطلاب ما يحفظه …\nلأن اعتقادهم باختصار ( ما منه فائدة ) …\n\nايضا اخوي … انا نصحته يروح الجمعية ويأخذه من هناك … لأن الإختبار بكره … ولا فيه وقت كافي للإنتظار …\nوإلى الآن ( حتى بعد وضعك لأحد المياجر ) انا انصحه يروح الجمعية ويأخذه …\nلأنه يحتاج أكثر من ميجر أو ميجرين للمذاكرة …\n\nاكرر شكري لك أخ ( ابو البترول ) عى وضعك للميجر … وان شاء الله بهمَّتك ( أنت والأخوة الأعضاء الكهربائيين ) …\nنبني قاعدة ملفات تكون مرجع للأخوة الطلاب في الفصول القادمة …\n\nكل الإحترام والتقدير … 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/old-exams-for-ee201-with-the-solution-please/104862/5", "user": "user8044", "ts": 1300177001000, "tid": 104862, "pn": 5}}', 1300177001000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p858057-ee201', 'stk-ahmed_alhntoshi', 'EE 201', 'info', '{"desc": "وعليكم السلام ورحمــة الله وبركاتــه …\n\nبخير علــك بخير ❤️\n\nذاكر النوتس لمعرفة معاني الاحرف وتعريفها وكيفية اجادها\n\nوالنوت لا يحتوي على امثلة ومسالة لذلك فهو غيــر كافي\n\nالكتاب طبعا تطبق الي فهمته بالنوتس وفيــه امثلة كثير طويلة ودسمة وتستحق ان تاخذ حيز 25 درجة : على فكرة بالميجر كل سؤال عليه 25 درجة يعني اربع اسالة … شوي صح ؟\n\nولتحميل سلوشن مانويل طـ 9 هنا\n\nhttp://www.4shared.com/file/65qaTIeK/electric_circuits_9e.html\n\nبعد ماتطبق الي فهمته من النوتس وتحل اسالة الكتاب الان جاء دور الاولد كزامز والسبب جميع المدرسين يرجعون اليها\n\nفتجد بعض التركات نسخ تمام عن اولد اكزام مــا …\n\nهذا كل شيء بالنسبة لنظري الـ 201\n\nاما الاب … متــعة … الاهم حضور اللاب … التركيز مع المدرس ومعرفة طرق التوصيل وما الفرق بين التوصيل العمودي والافقـي … وكيف اوصل المقاومات توازي او توالي …\n\nوكيف استخدم جهاز الاميتير والي وظفيته قياس التيار _ الفولت _ المقاومة …\n\nالاهم والاهم في الاب قياس المقاومات وهي على الطاولة فلا تمسكها بيــدك وتقيسها لان تيار الي في جسمك راح يغير القيمة وبالتالي يسبب لك مشكلة في قيمة المقاومة وبالتالي قيمة مختلفة للككرنت والفولت … > دوامة\n\nقبل خروجك من الاب ارسم الدائرة _ او صورها فهذا يساعدك على تذكرها وخصوصا كيف نسوي توالي وتوازي …\n\nاذا فعلت ما كتبته لك بخصوص اللاب اضمن لك 19.0 من 20 على الاقل\n\nلاب مانويل هنا\n\nhttp://arabsh.com/z44wj8mjxm2e.html\n\nوبخصوص جزء اللاب المتعلق باستخدام الكمبيوتر … روعة\n\nوهذا البرنامج\n\nhttp://www.mediafire.com/?1s9j8bxj99ejixb\n\nبالتوفيـــــــــق وفالك A+", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee201/108799/10", "user": "Ahmed_Alhntoshi", "ts": 1308852572000, "tid": 108799, "pn": 10}}', 1308852572000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p959495-ee201', 'stk-m7mdz', 'EE 201', 'info', '{"desc": "يا شباب انا متآكد ميه بالميه انه الفاينال هذا … آصعب فاينل مر ع الكورس !!\n١٢ سؤال و ١١ واحد منها يبي لها حـــــل و كتابة… وتركااات في كل سؤال !\n\nيا شباب … ترا كلنا كويسين و فاهمين المادة صح ! كلنا ذاكرنا صح و نستاهل احلا قريد\" كلنــــــــا \"\nيعني تظلمنا كلنا باختبار تعجيزي ! ما يصير …\nمو معناها افرجنا عال تجيب اصعب اختبار ! هذا تحدي يعني !!!!!!\n\nالافرج لاااااااااااااااااااااااازم يتحول الـــــــــ b لازم\nc جدا ظالمه !", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee201/117522/19", "user": "M7mDz", "ts": 1325766956000, "tid": 117522, "pn": 19}}', 1325766956000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p898939-ee201', 'stk-barhomitto', 'EE 201', 'info', '{"desc": "إن شاء الله الشباب يفيدونك\n\n^^\n\nأكثر رد يقهرني 🤠\n\nالمهم … بالنسبة للـ 201 كتابها معروف أفضل كتاب راح يمر عليك في دراستك الجامعة … خلي اعتمادك عليه 100%\nأي شي يفوتك في الكلاس لا تخاف… راح تلقاه في الكتاب ويمكن تفهم المعلومة من شرح الكتاب أحسن من شرح الدكتور… وراح يفيدك حتى في ee205\n\nبالنسبة للـ200 لما أخذتها أنا (في ترم 091) كنت أذاكر من نوت ممتاز جدا للدكتور شعراوي إن شاء الله يفيدك: تفضل حمل من هنا\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee200-ee201/111772/2", "user": "Barhomitto", "ts": 1315738500000, "tid": 111772, "pn": 2}}', 1315738500000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p545032-ee201', 'stk-_1012', 'EE 201', 'info', '{"desc": "الاسباب في تغييري لمواقع بعض المواد من وجهة نظري\n\nفي السفمور 1 قدمت مادة الاسلامي للسمستر الاول لان وجودها راح يكن الحلا اللي مع الدسم الموجود واقدر اقول ان المادة الصعبة الوحيده هنا هي فزكس 203 وعندك ماث 202 سهالات وبرضو ee 201 & ee 200 مواد تحتاج شغل لكن موب صعبه واقدر اقول انها اسهل مادتين في الكهرب فوجود الخمس مواد هذي مع بعض راح يخلي السمستر متوسط الضغط\n\nفي السفمور 2\nحطيت اربع مواد تخصص مع بعض بدون أي اضافات\nوانا قدمت 390 لتخفيف ضغط اللابات في الجونير ولان طبيعتها مختلفة عن بقية مواد الكهرب وبعيدة كل البعد عنها هي تقريبا ً coe مع شوية ics فوجودها مع الثلاثي المرح 203 و 205 و 207 راح يسوي تغيير وتنويع صحيح في انو ضغط لكن هذا هو تخصص الكهرب ولازم يكون فيه شوية ضغط\nوالمادة الاخطر هي 207 في هذا السمستر والمادة الاثقل وبدون منازع هي 203\n\nجونير 1 أن خليتوه ثلاث مواد دسمه ومادة اسلامي بس لانو السمستر الوحيد اللي فيه ثلاث لابات فقلت راح يكون وضعو سبشل وتكون المواد الدسمه 3 مواد على عكس بقية السمسترات اللي كل واحد فيها 4 مواد دسمه تقريبا وطبعا انا قدمت 370 واخرت 360 الى جونير 2 والسبب بسيط لان 370 اصعب من 360 بمرااااااحل و360 هي فاكهة الثيرد لفل وهذا كلام اغلب شباب الالكترك\n\nجونير 2 للوهلة الاولى الواحد يحس ان السمستر ضغط لكن هوا فيه شوية ضغط والسبب طبعا هو ال340 وبرضو الانقلش 214 لكن اللابات هنا 2 مو 3 يعني السمستر راح يكون متوسط الضغط مع المادة اللطيفة 360 والمادة الشبه لطيفه 315 مع عربي 301\n\nسنير 1 سنير برجكت مع مادتين الكتف بدون لابات مع مادة النمريكال ميثودز مع مادة اسلامي اشوفه شبه خفيف وما اتوقع انو راح يكون فيه ضغط مع السنير برجكت ويمكن بعض مواد الفور لفل تساعدكم في البروجكت\n\nسنير 2 احلى شيء انك تودع الجامعة بهذا الجدول اللطيف الظريف الخفيف الجميل اللي ما تحلم فيه بجامعة البترول وتترك اثر ايجابي قبل الوداع << قلم هندي\n\nان شاء الله الكلام كان مفيد", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/83738/5", "user": "_1012", "ts": 1266370034000, "tid": 83738, "pn": 5}}', 1266370034000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p46836-ee201', 'stk-user15', 'EE 201', 'info', '{"desc": "السلام عليكم ورحمه الله …\n\nأخوي (فلان ) مع إن السؤال موجه إلى (logic-man ) بس أنا ودي أشارك\n\nبالنسبه ل(EE201) بالصيف … أقول لاتنزلها بالصيف لأن هذي المادة ““بالذات”” ما أبالغ إذا قلت إنها أهم مادة في الهندسة الكهربائية …\n\nوالصيف 8 أسابيع يعني المادة راح تنسلق سلق … ( رأيي الشخصي )\n\nشف إذا مداك تنزل EE200 بالصيف ممتاز ( وما أتوقع ينزلوها بالصيف )\n\nو إذا ما نزلوا EE200 خذ\nMATH\nو IAS\nو PE\n\nهذي 6 ساعات و الشغل راح يكون في الماث\n\nو السمستر الأول\nخذ\nMATH\nEE201\nEE200\nIAS\nICS\n\nو بالنسبة ل EE200 الماده أولها سهل و يبدأ التعقيد آخر السمستر بس تراها بصراحه ( مادة قريد ) و سهله نوعاً ما\nو هي تتكلم عن (logic gate ) و فيها لا\n\nو دوائر الديجيتل و كتابها سهل و مفهوم و غالبا اسئلة الدكاتره ما تطلع من الواجبات\n\nبالنسبة ل EE201 هي أهم مادة في الكهرب و هي تتكلم عن حل الدوائر الكهربائية و فيها لاب و الحلو فيها كل ما تحل دوائر يزداد فهمك و العكس بالعكس يعني المادة يبليها متابعة أول بأول\n\nبالنسبة ل ICS103 وهي مادة برمجه ++C و أيضا سهله حيل إذا أخذتها عن KHAN,R ( مثل كلام الأخ logic -man) و أنا أقول إذا طلعت فيها أقل من +B مالك داعي لأنها سهله\n\nخلاصه / السفامور أول فصل هي فرصتك لرفع المعدل بشكل كبير جداً … بس أهم شي أنك تعزم النية وتوكل على الله\n\nأخوك/ مهندس كهربائي 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/34208/8", "user": "user15", "ts": 1081218485000, "tid": 34208, "pn": 8}}', 1081218485000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1164338-ee201', 'stk-user7645', 'EE 201', 'info', '{"desc": "للأمانة درست مع الإثنين\n\nكلهم دكاترة محترمين لكن بأكتب تجربتي عن كل شخص فيهم :\n\nد. الدويش :\n\nEe 201\nشرحه عادي وتصحيحه لابأس فيه ، كويزاته سهله واحياناً يخلينا نحل مثال قبل مايبدأ هو بشرحه . كان لابأس فيه مقارنة بكونه مانزل المادة من عشر سنوات . التعامل عادي ولابأس فيه حتى لو حبيت تراجع ورقتك ، الدكتور نوعاً ما متكاسل لكن مو مهم مادام تقدر تطلع عنده بقريد كويس .\n\nأتذكر حذف البروجكت بالـ 201 وغيرنا عمله ، ماادري من باب المساعده ولا الكسل بالتصحيح 😆\n\nEe205\n\nللأسف د.باخشوين مو مثل ماسمعت عنه أو يقولون عنه بالمنتدى إنه شريح ممتاز !! شرحه آفرج إذا مو أقل من الأفرج ، كان يفتح لنا السلايدات اون لاين ويبدأ يتكلم منها ويحل المسائل الموجوده فيها وأحياناً يطلعنا على السبورة نكتب عنه .\n\nالتعامل بتعالي لاحظت هذا الشيء من خلال طلاب راجعوه بالمسائل بالإختبار ، والتصحيح سيء جداً ممكن يخسف عليك درجة سؤال كامل في حال غلطت ببداية السؤل فقط .\n\nالكويزات بعضها يتعمد وضعها بطريقة يسهل تصحيحها على نفسه ، مثلاً ببعض الكوزات كان يجيب لنا سؤال تحط الإجابة النهائية بالبوكس ، إذا كانت الإجابة صحيحة فيراجع الخطوات … أما إذا كانت خاطئة فأنسى الأمر بدرجة منصفة لباقي حلك للسؤال .\n\nيحب الأسئلة التعجيزية في بعض الأحيان مو مثل مايشرحلك .\n\nبالنسبة لي د.دويش أفضل من د.باخشوين ، وكلهم اساتذتنا ونحترمهم لكن هذه وجهة نظري .\n\nبالتوفيق لك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/138374/4", "user": "user7645", "ts": 1358200960000, "tid": 138374, "pn": 4}}', 1358200960000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p790349-ee201', 'stk-abdibr116', 'EE 201', 'info', '{"desc": "في معلومة أحب أن أدلي بها على طاري الفهم والتطبيق…\n\nالهندسة الكهربائية من العلوم القوية، ولكن للأسف القسم يقدمها بشكل سيء، وحكمت على ذلك بعد دراسة ثلاث كورسات (ee201, 203 & 207) بالإضافة إلى سؤال الكثير من الزملاء في تخصص الكهرباء…\nالدكاترة في قسم الكهرباء يهتمون كثيرا في كيفية حل المسائل وليس في جانب الفهم والتطبيق، وإن أردت الحصول على أعلى الدرجات فعليك بكثرة الحل وإن كان بغير فهم.\nأما في هندسة الحاسب، فالهدف الأول والأخير هو فهم النظرية والتطبيق، وبناءً على ذلك تقدم الاختبارات، ولك أن تسأل الطلاب من هنا ومن هناك بنفسك … وابتعد عن المسوقين، لأن اختيار التخصص يعتمد على الميول الشخصية، وأنصحك بشدة زيارة الأساتذة من القسمين وعرض ميولك عليهم…\nنصيحة أخيرة: عمل جهاز الجوال وكذا صناعة السيارات لا تعتمد على تخصص محدد ولا على مجال واحد، وإنما مجموعة من العلوم تتحد فيما بينها لتخرج الابداعات.\nمعلومة: في بعض الطلاب آخذين مقلب في تخصصاتهم… الله يعينهم.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/computer-eng-vs-electrical-eng/102237/26", "user": "abdibr116", "ts": 1297712877000, "tid": 102237, "pn": 26}}', 1297712877000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p643052-ee201', 'stk-user4529', 'EE 201', 'info', '{"desc": "شوف الدكتور علي الشيخي أخذت عنده ee201 و كانت سمعته طيبة بنسبة لي\n\nأخلاقه عالية و ما عليها كلام بس أنا ما ارتحت للدكتور أبدا\nبالإضافة إلى أن سفراته واجد يعني الميك اب في الليل كان واجد\n\nو تشعر أنه يتعب في المادة بس شرحه مخربط يعني كل شابتر له طريقه\n\nبس صراحة رغم أني ما ارتحت له لكن أنه ساعدني في القريد", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/90762/3", "user": "user4529", "ts": 1277329225000, "tid": 90762, "pn": 3}}', 1277329225000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p899674-ee201', 'stk-daredevil', 'EE 201', 'info', '{"desc": "باالنسبه لل ee 201 فهذي الماده مالك غيرها الا الكتاب ولاتهمك اي ملخصات ثانيه ولا شي … تابع الكتاب اول باول فهو مررره ممتاز والاكسامبل والبروبلمز للكتاب تغطيك كل شي في المنهج والمنهج من الاساس يعتبر سهل جداا بس اصعب شي بيتعبك في هالكورس وكورس ال ee 200 هو الافرج العالي فخل هدفك الدرجه الكامله في كل الاختبارات\n\nباالنسبه لل ee 200 فاعذرني انا ناسي الماده لاني من زمان ماخذها بس الماده تعتبر من سهله الى متوسطه وهي اساس الديجيتال والماده متراكمه يعني لازم تفهم اول باول … الكتاب في هاالماده عادي جدا لكن عندك نوتات الشعراوي جداا ممتازه ونوتات الدكتور داوود مختصره ومفيده للمراجعه … اكثر شي بتعاني فيه مع هاالماده هو ان الاكسامبلز قليله فحاول انك تروح للاوفيس اور كثير وراجع مع الدكتور اسئلة الكتاب او المياجر", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/111836/4", "user": "DareDevil", "ts": 1315801793000, "tid": 111836, "pn": 4}}', 1315801793000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p43763-ee201', 'stk-logic-man', 'EE 201', 'info', '{"desc": "للدكتور طبعا الحق كله انه يقلب الافرج الى ستاندرد والعكس وبالمناسبة انا صار لي موقف مع دكتور ماودي اذكر اسمه في مادة EE201 يعني اذكر خذيت الميجر الاول علامة كامله والثاني نقصتني بس علامة والكوزز كلها اوكيييك والهوم ورك كامل ولا غياب وحليت الفاينل كله ماعدا نص سؤال ودرجة اللاب كانت تمام بس للاسف انتظرت درجة الفاينل شنو تتوقعون يعني؟ B بالله شلوووووووووووووووووووون؟؟ هذي اخس درجة حبطت معنوياتي بالجامعه كلها لاني فعلا فعلا انظلمت فيها:(", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/31721/4", "user": "logic-man", "ts": 1077101380000, "tid": 31721, "pn": 4}}', 1077101380000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p511276-ee201', 'stk-user2536', 'EE 201', 'info', '{"desc": "لافت نظر\nطبعا تقدر تخلي مواد العربي والاسلامي لبعدين بالاضافة معاهم عندك free elective تختار اي مادة براحتك وتدرسها …\nوتفكيرك سليم وانا تقريبا مسوي نفس الشيء …\n\nبالنسبة للجدول اللي انت حطيته يعني ما عليه …\nالـ EE 201 مذاكرة مياجر ومثلها الـ ME215 … ولابات هالمادتين بسيطة ماهي صعبة … والـ 325 ماهي صعبة بس كويزات وهووم وركات ومياجر سهلة مع الروقي … الإنجلش تعرفها أكيد اشغالها واجدة وبتطفشك بالترم بكثر خرابيطها !\nيعني بشكل عام عندك مذاكرة مياجر للكهرب والـ325 والـ215 … ومادة كرف اللي هي الانجليزي 🙂\n\nجدول مهب صعب وحليو بس انتبه لا تهمل اي مادة ترى الكهرب والـ 215 بـ 4 كريدت يعني اي تخبيص بتطيحك تحت وفوق هذا الانجلش قريداتهم زي وجييهم يعني بيروح عليك الترم بخسارة 😦", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/092-ise/80839/170", "user": "user2536", "ts": 1262085880000, "tid": 80839, "pn": 170}}', 1262085880000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p461734-ee201', 'stk-user2760', 'EE 201', 'info', '{"desc": "اهلين ابو سالم … تخصصك ise اكيد … وخلني اكلمك بحكم اني من نفس تخصصك …\n\nانا اخذت نفس جدولك ذا … بس الفرق كان عندي بدل الانجلش … كان عندي ee201 … وال ise 201 ( كانت ساعتين ) … والحمد لله شديت حيلي وطلعت بأحلى ترم بحياتي …\n\nانت لو معدلك نازل … المفروض تنتهز الفرصه بالترم ذا … ترم خفيف وسهل … وانا اشوف انه معقول\nالانجليزي ما اقدر اتكلم فيها … بحكم انها مادة تعتمد على المدرس حقك …\nالكيمياء … والله حبيتها الماده ذي … يبيلها شوية مذاكرة … والرياضيات … والله مدري شقول لك … مادة حل تمارين … تحل تمارين كثير تفهم … ما تحل … مع السلامه …\nوالمواد الباقيه … حضورك يكفيك … اتمنى اني افدتك … وسلام عليكم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/77713/2", "user": "user2760", "ts": 1253329675000, "tid": 77713, "pn": 2}}', 1253329675000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p145678-ee201', 'stk-theotherpart', 'EE 201', 'srcU', '{"html": "السلام عليكم<br><br>الفزعه ياهل الفزعه !!!!!!!!<br><br>انا ادمي لي اسبوع على بروجيكت ee201<br><br>ولا قدرت عليه وبكره تسليمه…<br><br>والمشكله اذا 201 وماقدرت عليه كيف الباقي<br><br>بس انا حليت 80% بس وقفت عند كيف احسب power<br><br>HEEEEELLLLLLLPPPPP !!!!!<br><br>​<span data-fid=\"stk-f145678-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f145678-0": {"name": "Design project ee201.pdf", "v": "data:application/pdf;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee201/54395/1", "user": "theotherpart", "ts": 1168888169000, "tid": 54395, "pn": 1}}', 1168888169000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p145449-ee201', 'stk-a_student', 'EE 201', 'srcU', '{"html": "ياشباب انا جايب الحفلة في Ee201 يعني احس ان F والعياذ بالله بتنطبع في الترانسكربت حقي…<br><br>ياليت لو تساعدوني في البروجكت لأني مو فاهم وش الطريقة … وهل هو هاردوير ولا ريتن…<br><br>وهذا البروجكتس في المرفقات…<br><br>انا داخل على الله وثم عليكم…<br><br>اخوكم … المهاجر<br><br>​<span data-fid=\"stk-f145449-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f145449-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f145449-2\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f145449-0": {"name": "EE 201-Project.doc", "v": "data:application/msword;base64,"}, "stk-f145449-1": {"name": "EE 200 project.pdf", "v": "data:application/pdf;base64,"}, "stk-f145449-2": {"name": "EE200 project outlines.pdf", "v": "data:application/pdf;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee201/54379/1", "user": "A_student", "ts": 1168780633000, "tid": 54379, "pn": 1}}', 1168780633000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p146004-ee201', 'stk-user1091', 'EE 201', 'srcU', '{"html": "بسم الله<br><br>ال Opamp الثالث أنا حاطه حتى يعطيك علامة الماينس اللي موجودة جنب ال 100<br><br>ال t و V1 و V2 البروجكت ما يبغى قيمهم<br><br>البروجكت يبغاك تسوي Design<br><br>يعني تختار قيم الرسيستور والكباسيتور حتى يطلع عندك الانتجريشن مضروب في 100-<br><br>شف المرفق الله لا يهينك<br><br>​<span data-fid=\"stk-f146004-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f146004-0": {"name": "Doc1.doc", "v": "data:application/msword;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee201/54379/7", "user": "user1091", "ts": 1168985799000, "tid": 54379, "pn": 7}}', 1168985799000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p801204-ee201', 'stk-user6130', 'EE 201', 'srcU', '{"html": "تفضل<br><br>​<span data-fid=\"stk-f801204-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f801204-0": {"name": "EE201 Syllabus.pdf", "v": "data:application/pdf;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee201-syllabus/103792/2", "user": "user6130", "ts": 1298754455000, "tid": 103792, "pn": 2}}', 1298754455000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p911652-ee201', 'stk-user6008', 'EE 201', 'srcP', '{"html": "إذا تقصد الأسئلة فهذي هي بالمرفقات<br><br>​<span data-fid=\"stk-f911652-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f911652-0": {"name": "HW2.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/93e994c3b90a8e2fe8145ccf43643b6cd3fbdf10da62f400a74fa7ea7f8666ae"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee201/113089/2", "user": "user6008", "ts": 1317472559000, "tid": 113089, "pn": 2}}', 1317472559000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p905991-ee201', 'stk-user7645', 'EE 201', 'srcU', '{"html": "تفضل ياغالي 👍<br><br>​<span data-fid=\"stk-f905991-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f905991-0": {"name": "EE201_111.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/2d0e3382e4a562fa2a6c0c9d4d0b6b5410185cbc5ff0ae07dd077a1fea1c9cf9"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee201/112534/2", "user": "user7645", "ts": 1316563766000, "tid": 112534, "pn": 2}}', 1316563766000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p871100-ee201', 'stk-madridi-4', 'EE 201', 'srcP', '{"html": "السسلام عليكم<br><br>بالتوفيق شباب باختباراتكم , فتحت ذا الموضوع عشان اللي عنده شي يفيدنا فيه بميجر ون مثلا اولد اكزام محلول او اسئله مناقشة وزي كذاا 🤠<br><br>يعطيكم العافيه<br><br>انا ببدأ , بالمرفقات ميجر ون 102 👍<br><br>ننتظر فزعتكم<br><br>​<span data-fid=\"stk-f871100-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f871100-0": {"name": "exam 1 _102.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/616de3e4c9e85b24289eaac1314050faa08d92acaa72794e610d697fbf750438"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee201-1/109837/1", "user": "Madridi-4", "ts": 1310876646000, "tid": 109837, "pn": 1}}', 1310876646000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p871625-ee201', 'stk-a-t-m', 'EE 201', 'srcP', '{"html": "أفا عليك حنا موجودين 🤠<br><br>هذه أولد إكزامز محطوطة على الويب سيتي<br><br>للأسف المحلول بس واحد اللي هو حق 101 موجود هنا<br><br>http://www.mediafire.com/?yo603w2qwx8j33w<br><br>بالتوفيق للجميع ❤️<br><br>​<span data-fid=\"stk-f871625-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f871625-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f871625-2\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f871625-3\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f871625-4\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f871625-0": {"name": "EE 201_092_Major 1.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/35e3fffc16d514af1cace2b72ec88305108d8ed54c4eeeb5048a120b0c033d6e"}, "stk-f871625-1": {"name": "EE 201_091_Major 1.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/5ccf3dcc18852efb1422d2a44f5bc89e1e8111676f2d26e966834fbaaa2f74fe"}, "stk-f871625-2": {"name": "EE 201_083_Major 1.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/05ddda4c3c36dd83465923df0ebd0f4aef9e76c2d7c18860896cb390bda80074"}, "stk-f871625-3": {"name": "EE 201_081_Major 1.pdf", "v": "data:application/pdf;base64,"}, "stk-f871625-4": {"name": "EE 201_082_Major 1.pdf", "v": "data:application/pdf;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee201-1/109837/4", "user": "A-T-M", "ts": 1310972163000, "tid": 109837, "pn": 4}}', 1310972163000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p814800-ee201', 'stk-barhomitto', 'EE 201', 'srcP', '{"html": "بحثت لك في ملفات جهازي القديمة<br><br>ولقيت لك ميجر 1 للترمين 091 و 092 وطبعا مع الحلول<br><br>===== رسالة للأخ ليل المسافرين والأخوان =====<br><br>ليه التحطيم وكل ماجاء أحد يطلب شي قلتو مافيه ولا روح الجمعية؟؟؟<br><br>ساعدو الناس زملائكم يا اخي ترا المادة 201 أهم مادة في التخصص<br><br>طبعا أنا جبتها من جهازي لأني أخذت المادة ذي في ترم 092<br><br>وطبعا أنا متأكد إنها موجودة في أجهزة ناس كثير بس ماحد يبغى يساعد<br><br>ترا كل الدكاترة ينزلون حلول المياجر ويحطها في الويب سيتي<br><br>وش يضرك لو سويت لها داونلود وتنفع فيها غيرك للمستقبل؟؟<br><br>سبحان الله… انا طالب قديم ومفحط في الكهرباء وعانيت من قلة التعاون في المنتدى ذا<br><br>ولكن البركة في الدفعات الجديدة إن شاء الله<br><br>والله يوفق الجميع<br><br>​<span data-fid=\"stk-f814800-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f814800-0": {"name": "EE201_M1.zip", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/357d5845b0f601ef72ed5185222cdb302c13e03e1b53fab99215ac440d89a966"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/old-exams-for-ee201-with-the-solution-please/104862/4", "user": "Barhomitto", "ts": 1300174044000, "tid": 104862, "pn": 4}}', 1300174044000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p815254-ee201', 'stk-user5589', 'EE 201', 'srcP', '{"html": "سوري على التأخير …<br>هذي ميااجر قديمة معا حلها …<br>وبالتوفيـــق<br><br>​<span data-fid=\"stk-f815254-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f815254-0": {"name": "m#1.zip", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/2af91c3b0a0cd8c87d4040341123dac92a8f3289bc73dfac78daa7ff014564fd"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/old-exams-for-ee201-with-the-solution-please/104862/7", "user": "user5589", "ts": 1300215078000, "tid": 104862, "pn": 7}}', 1300215078000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p723287-ee201', 'stk-_student', 'EE 201', 'srcU', '{"html": "تفضل هذي نسخة من السيلابس مع تواريخ تسليم الهوموركات. 🙂<br><br>​<span data-fid=\"stk-f723287-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f723287-0": {"name": "EE201_syllabus_101.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/c567153b352a90ee4461be699dbe5304a5819d349f97f27561e290a85b5b2fe4"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/96829/4", "user": "_student", "ts": 1287416496000, "tid": 96829, "pn": 4}}', 1287416496000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p923430-ee201', 'stk-user5958', 'EE 201', 'srcP', '{"html": "^^<br><br>تفضل<br><br>​<span data-fid=\"stk-f923430-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f923430-0": {"name": "EE 201ExamIFall 2011_sol.zip", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/760e2b25663ae50a0a82e0d130efe1e804cc00d8367ebde25daa29b0c2001c25"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/113742/40", "user": "user5958", "ts": 1319225842000, "tid": 113742, "pn": 40}}', 1319225842000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-es_engineer-ee201', 'stk-es_engineer', 'EE 201', 'doc', '{"docs": [{"id": "stk-dr-f98371", "n": "Dr. A Zidouri", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "المادة ee 201\n\nالتحضير : كل محاضرة\n\nطريقة الشرح : حل تمارين وامثلة على السبورة …\n\nالكويزات : بسيطة جدا من افكار اسئلة الكتاب\n\nالتصحيح : افضل دكتور في التصحيح لهذي المادة !!! تاخذ قريد ما تحلم فيه\nاهم شي لا تترك ولا شي فاضي\n\nالقريد النهائي: A+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p739882-ee201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-zidouri/98371/2", "user": "ES_Engineer", "ts": 1290903558000, "tid": 98371, "pn": 2}}]}', 1290903558000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-c.k.s-ee201', 'stk-c.k.s', 'EE 201', 'doc', '{"docs": [{"id": "stk-dr-f98371", "n": "Dr. A Zidouri", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "المادة : ee 201\nالتحضير بشكل يومي\n\nالكويزات من النوت حقه مع تغيير شبه لا يذكر\n\nالتصحيح اشوفه يعطيك اكثر من حقك بشيء بسيط\n\nB", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p742312-ee201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-zidouri/98371/4", "user": "C.K.S", "ts": 1292135299000, "tid": 98371, "pn": 4}}]}', 1292135299000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mega_mind-ee201', 'stk-mega_mind', 'EE 201', 'doc', '{"docs": [{"id": "stk-dr-f98371", "n": "Dr. A Zidouri", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أنا درست معه ee201 term 101\n\nالتحضير :كل كلاس يحضر بس أتوقع تحضير شكلي فقط (بالنسبة له)\nطريقة الشرح : يشرح غالباً على السبوره ويستخدم السلايد فقط لتوضيح الدوائر الكهربائية. شرحة حلو جدا في الماده وهي سهله الماده أصلاً.\nالكويزات : كل شابتر عليه كويز من الهوموورك أو الكتاب\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي: أعطية B\nالصوت:,واضح\nإضافات\nالدكتور مره طيب وأخلاقة جدا عالية ويحب اللي يشتغلون معه .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p829676-ee201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-zidouri/98371/7", "user": "Mega_Mind", "ts": 1301812655000, "tid": 98371, "pn": 7}}]}', 1301812655000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-majed_sami_alghamdi-ee201', 'stk-majed_sami_alghamdi', 'EE 201', 'doc', '{"docs": [{"id": "stk-dr-f98371", "n": "Dr. A Zidouri", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE201 - T222\nالتحضير :\nفي أول خمس أسابع كان الدكتور يحضر تقريبا كل يوم ومعظم الأحيان يكون نهاية الكلاس عن طريق السيريال نمبر بعدها بدأ الدكتور في التساهل في التحضير لكن في حال رأى غياب كثيريحضر.\nالدكتور لا يحب الـتأخير، ولا يحب الذي يحضر ثم يذهب إلى دورة المياه أو الكافتريا، وقد ينفعل الدكتور إذا تكرر هذا الشيء منك.\nطبعا الحضور والمشاركة عليهم 4% من الكلاس ورك و الدكتور أعطى غيابين مجانية لكل طالب.\n\nطريقة الشرح :\nشرح الدكتور متوسط، وهذا الأمر يختلف من طالب لطالب لأني للأمانة لم اكن أعتمد عليه لتوفر الكثير من المصادر لكن كنت أحاول الاستفادة من شرح الدكتور قدر المستطاع.\nالدكتور لديه مميزات كثيرة أحداها أنه يعطي الطلاب فرصة في الكلاس خاصة قبل المياجر لحل أسئلتهم على السبورة بالتفصيل سواء كانت من الاولد اكزام أو أسئلة الكتاب.\n\nالكويزات : متوسطة إلى سهلة.\nكانت أسئلة الكويزات تقريبا نفس أسئلة الكتاب مع بعض التغير ومرات قليلة كان يجيب من الاولد أكزام.\n\nالمياجر: كومن\nMajor 1 كان المواضيع بسيطة وسهلة وغالبا يكون الافريج مرتفع لذلك لا تفرط فيه\nMajor 2 المتيريال يبدأ يصعب مقارنة بمتيريال الميجر الأول وغالبا الافريج راح يكون أقل من ميجر 1\nالفاينلات : كومن\nباقي ما اختبرت لكن على كلام الدكتور أن الفاينل يعتمد على الافريج يحاولون يخلون الافريج 70-75%\n\nالقريد النهائي: B\nالصوت: منخفض قليلا و لغة الدكتور ممتازة وواضحة\nإضافات:\n- الدكتور أخلاقة عليه.\n- الدكتور لا يدقق في التصحيح سواء في الهومورك وكذلك في المياجر و الكويزات وراح يعطيك أكثر من حقك.\n- الكورس هذا بالذات تحتاج تتدرب كثير فقط لأن الكوسبت سهل جدا.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536708-ee201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-zidouri/98371/37", "user": "MAJED_SAMI_ALGHAMDI", "ts": 1684833217000, "tid": 98371, "pn": 37}}]}', 1684833217000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m77a_alkhraimi-ee201', 'stk-m77a_alkhraimi', 'EE 201', 'doc', '{"docs": [{"id": "stk-dr-f98373", "n": "Dr. Abdullah Al-Ahmari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عند الاحمري ee201 وكان الكورس سهل ومفهوم وميزت الاحمري يكتب نوت ويغير طرق بعض القوانين عن الكتاب عشان يسهلها بس لازم تحدد من البدايه من وين بتذاكر عشان ماتلخبط بين الطرق حقت الاحمري والطرق الي فالكتاب. الشرح ممتاز والتحضير يوميا في بداية الكلاس و الدكتور جدا متعاون مع الطلاب والتصحيح حلو يعني تاخذ حقك وزياده والمشكلة عند الاحمري انه يعطي ثلاث كوزات بس في الترم والكوز عليه درجات كثير. في النهايه انصح به وبشده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p877383-ee201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdullah-al-ahmari/98373/13", "user": "M77a_Alkhraimi", "ts": 1312016388000, "tid": 98373, "pn": 13}}]}', 1312016388000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_only-ee201', 'stk-_only', 'EE 201', 'doc', '{"docs": [{"id": "stk-dr-f98373", "n": "Dr. Abdullah Al-Ahmari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت عنده ee201 في فصل 091 … بداية السمستر كان شرحه مقبول إلى الميجر الأول، بعدها بدأ يسرع في شرح المتيريال لأنه كان متأخر … تصحيحيه في المياجر سيئ جداً … التحضير كل كلاس و ينادي على الأشخاص واحد واحد … الصراحة لا أنصح به أبداً … تقييمي النهائي له c", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p898800-ee201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdullah-al-ahmari/98373/15", "user": "_ONLY", "ts": 1315719881000, "tid": 98373, "pn": 15}}]}', 1315719881000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-prince-abod-ee201', 'stk-prince-abod', 'EE 201', 'doc', '{"docs": [{"id": "stk-dr-f98377", "n": "Dr. S. Al-Ahmadi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "لاب ee 201 - ترم 101\n\nمدرس جديد ، تخرج من الجامعة في التسعينات وكمل الدراسة في أمريكا وكندا ورجع يدرس هنا في أول سمستر له …\nاللاب كان معاه إبدااااااااااااااع ، لا بري لاب ولا ريبورتات ولا واجبات و كويزين طول السمستر كل واحد أتفه من الثاني …\nكل اللي تسويه ، تسوي التجربة ويشيك على الارقام ، يعطيك ورقة وتجاوب على الاسئلة نهاية كل لاب وتسلمه الورقة وتمشي …\nأعطانا فاينال متوسط ، كان فيه كذا سؤال يعتمد على فهمك للكتشر …\nالدرجات في النهاية سوا فيها فارييشن جيد بين 12 و 18 من 20 …\n\nطلابه في الليكتشر يشتكون من صوته الواطي وضعف ايصاله للمعلومة ، لكني وجدته انسان فاهم مرة من خلال اكثر من حاجة شرحها لنا في اللاب ما كنا فاهمينها في الليكتشر …\n\nبصراحة انصح به في اللاب …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p779438-ee201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-al-ahmadi/98377/7", "user": "prince-abod", "ts": 1296459437000, "tid": 98377, "pn": 7}}]}', 1296459437000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-shmaiz3r-ee201', 'stk-shmaiz3r', 'EE 201', 'doc', '{"docs": [{"id": "stk-dr-f98377", "n": "Dr. S. Al-Ahmadi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت معه 101 لكتشر ee201\n\nالتحضير : بالاسم\nطريقة الشرح : يحل أسئلة الشرح اللي بالكتاب\nالكويزات : سهلة إلى متوسطة (6كويزات)\nالمياجر:------كومن\nالفاينلات : -----كومن\nالصوت: واضح ولكن بطيء جدًا****القريد النهائيD\nإضافات : يشرح للسبورة ونادرًا ما يواجهنا وهو يتكلم. الأفرج كان عنده معدوم مقارنة بالسكاشن الثانية. الكلاس ورك يعطيك حقك بالمللي. خلوق جدًا ويرحب بالأسئلة أثناء الشرح لكن يعيبه البطئ وبالتالي يصير الفصل نايم.\n\nلا أنصح به أبداً وإذا كان فيه شيء إيجابي هو أخلاقه العالية فقط.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p788642-ee201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-al-ahmadi/98377/9", "user": "ShMaiz3R", "ts": 1297605310000, "tid": 98377, "pn": 9}}]}', 1297605310000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-eng_mohamed-ee201', 'stk-eng_mohamed', 'EE 201', 'doc', '{"docs": [{"id": "stk-dr-f98387", "n": "Dr. Mesbah Wessam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE 201 - 111\n\nالتحضير :\nآخر كل كلاس ينادي على الأسماء\n\nطريقة الشرح :\nسلايدات مع كتابة ملاحظات على السبورة مثل اشتقاق القوانين وحل الأمثلة\nالشرح واضح\n\nالكويزات :\nمن متوسطة إلى صعبة\n\nالمياجر:\nالفاينلات :\nكومون\n\nالقريد النهائي:\nA\n\nالصوت:\nواضح\n\nإضافات :\nالحمد لله أنا كنت مرتاح معاه في المادة ، يصحح على المانيوال ، لكن ميجر 2 والفاينل كان بطريقة الmultiple choice ، يعني يا تاخد عشرة أو صفر في السؤال …\nفي النهاية أنصح به", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p978552-ee201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mesbah-wessam/98387/14", "user": "Eng_Mohamed", "ts": 1328189642000, "tid": 98387, "pn": 14}}]}', 1328189642000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6737-ee201', 'stk-user6737', 'EE 201', 'doc', '{"docs": [{"id": "stk-dr-f98387", "n": "Dr. Mesbah Wessam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ee 201 - 112\n\nالتحضير :\nآخر كل كلاس ينادي على الأسماء\n\nطريقة الشرح :\nيفتح سلايد ويشرح ويفصل فيه على السبورة ويخليك تفهم كيفية اشتقاق القوانين ويفصل تفصيل رائع وكافي ووافي للكونسبت ويحل أمثلة عن أهم الأمثلة و يشرحها حبة حبة و يربط الكورس باستخدماته في الواقع\n\nالكويزات :\nمتوسطة للمذاكر طبعاً\n\nالمياجر:\nكومون\nالفاينلات :\nكومون\n\nالقريد النهائي:\nA+\n\nالصوت:\nواضح جداً\n\nإضافات :\nأنا حاذف سمستر وعايد الكورس ودرست المادة عند دكتورين آخرين بصراحة د. وسام الأفضل بكثييير و لو أحصله في أي كورس ما أتردد وطبعاً يحذف أسوء كوز وبروجكته كان سهل جداً جداً و يرفع لك الكلاس وورك تقريباً 4 درجات\nالتصحيح مثله مثل بقية الدكاترة لا هو التوب ولا هو السيء أنصح به وبقوة وطبعاً يذكرك بالأشياء اللي فاتت قبل البدء في حل التمارين", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1048540-ee201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mesbah-wessam/98387/16", "user": "user6737", "ts": 1338468885000, "tid": 98387, "pn": 16}}]}', 1338468885000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-euler-ee201', 'stk-euler', 'EE 201', 'doc', '{"docs": [{"id": "stk-dr-f118660", "n": "Dr. Naveed Iqbal", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم :\n\nEE201 Lab****التحضير : يحضر كل لاب , تتأخر مايقولك شي 🌹\n\nطريقة الشرح : يشرح سريع ع السبورة , وتبدون تشتغلون حسب اللي مكتوب باللاب , 👍\n\nالكويزات : كويزات سهلة , بعضها نظري وبعضها عملي , 🌺\n\nالقريد النهائي: B+\n\nالصوت: موب واضح بس تفهم عليه أحيانا ,\n\nإضافات : المدرس حبوب ومستعد يشرح لك اكثر من مرة وماعنده مشكلة , وتصحيحه للريبورتات بطل = الافرج صار مرة عالي , = عطانا فاينال صعب( نظري ) ع حسب تقييم الطلاب , لأن يعتمد ع فهمك للمادة ,و(عملي) وكان سهل , 🌹\n\nباختصار , لايفوتك , 👍", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1077543-ee201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/naveed-iqbal/118660/10", "user": "Euler", "ts": 1344388783000, "tid": 118660, "pn": 10}}, {"id": "stk-dr-f98387", "n": "Dr. Mesbah Wessam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE201 _ Lec\n\n**التحضير :**آخر الكلاس ينادي على الأسماء ومايسمح لك تدخل لو تأخرت 10 دقايق , 🌹\n\nطريقة الشرح : من السلايدات ويشتق القانون ع السبورة ويحل لنا كم مسألة من السلايدات او من الكتاب , 🌺\n\nالكويزات : كانت سهلة نوعا ما , بس الوقت ضيق يعني يبغالك ماتضيع وقت بالتفكير , 👍 ياخذ احسن 5 كويزات طبعن , 🤴\n\n**المياجر:**كومون\n**الفاينلات :**كومون\n\n**القريد النهائي:**A+ بجدارة , 🤴\n\n**الصوت:**واضح جداً\n\n**إضافات :**تصحيحه بالمياجر + قريد ولا أحلى , غير كذا أسلوبه ف توصيل المعلومة , ويحاول يجيب تطبيقات للدرس عمليا , 🙂\nأيضا البروجكت كان سهل , 🌹\n\n= لايفوتك , 👍", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1077604-ee201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mesbah-wessam/98387/17", "user": "Euler", "ts": 1344395288000, "tid": 98387, "pn": 17}}]}', 1344388783000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-a_s_m-ee201', 'stk-a_s_m', 'EE 201', 'doc', '{"docs": [{"id": "stk-dr-f98492", "n": "Dr. Adil Balghonaim", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "لابأس فيه للـ ee201\nتصحيحه زي كل المدرسين على السلوشن.\nميزته خفيف دم وكوزاته سهله.\nمع اني طالب سستم بس أحس شرحه كويس وافضل من غيره.\nفي النهاية احب انصحكم بالأونلاين كورس لايفوتك.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1035389-ee201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/adil-balghonaim/98492/19", "user": "A_S_M", "ts": 1336654924000, "tid": 98492, "pn": 19}}]}', 1336654924000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user7645-ee201', 'stk-user7645', 'EE 201', 'doc', '{"docs": [{"id": "stk-dr-f98522", "n": "Dr. Husain Al-Dawish", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "مادة ee201\n\nاعتقد انه الدكتور الوحيد اللي مايعطي DN لإني اشوف طلاب مايحضرون ابداً للكلاسات ودايما قليل بالكلاس .\n\nشرحه بالنسبة لي ممل واحسه يشرح بدون نفس ، كويزاته سهله وسؤال مباشر واحد .\n\nانصح انك تنزل معاه خصوصاً وان المادة سهله الفهم وتقدر تذاكر لحالك من السلايدات وتفهم او من الكتاب .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p932207-ee201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/husain-al-dawish/98522/10", "user": "user7645", "ts": 1321544841000, "tid": 98522, "pn": 10}}]}', 1321544841000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_prince-ee201', 'stk-_prince', 'EE 201', 'doc', '{"docs": [{"id": "stk-dr-f98522", "n": "Dr. Husain Al-Dawish", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ee 201\nترم 111\n\nالتحضير :\nطريقة الشرح : على السبورة …والنوت حقه محترم لو كنت تتابع معاه اول باول …يعطيك الزبدة بالمختصر المفيد يعني كل درس يحل عليه مثال ولا اثنين …النوت حقه تقريبا كان مغطي مالا يقل عن 80% من افكار الكتاب\nالكويزات : احنا اخدنا اربعة كوزات لكن حذف واحد لان يقول اغلب الطلاب جايبين 0 والباقي سهالات (وكان ما يتأخر في ترجيعها هي والمياجر !!)\nالمياجر: المياجر سهالات…وتصحيح المدرس حلو يعني مايدقق كثير\nالفاينلات :تعرف وش معنى كلمة صلخ …اعظم منها (السمسترات اللي راحت الفاينل كان 6-8 اسئلة واحنا 12 سؤال كل واحد يقول الزود عندي )ونظامهم الغبي اختيارات لكن اذا اخترت صح بدون حل صفر واذا حليت وغلطت في اخر رقم هم صفر << نظام غبي\nالقريد النهائي: B+\nالصوت:,واضح والدكتور طبيعته بااارد جدا\nإضافات :الله يوفقه اعطى مجموعة من الشباب فل في الكلاس وورك وكثير اخذو فوق 17…وحسبته كانت على الكوزات والهوموركات وبعدين زاد كل الطلاب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p959843-ee201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/husain-al-dawish/98522/11", "user": "_PrInCe", "ts": 1325796733000, "tid": 98522, "pn": 11}}]}', 1325796733000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-saudi_kfupm-ee201', 'stk-saudi_kfupm', 'EE 201', 'doc', '{"docs": [{"id": "stk-dr-f98522", "n": "Dr. Husain Al-Dawish", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ee201\n\nصراحة أستغرب من الطلاب اللي يمدحونه … المدرس سيء لأبعد درجة … الشرح من غير نفس …شايف نفسه على الطلاب … دائما هو صح حتى لو كان غلطان … صراحة واحد من أسوء المدرسين اللي نزلت عندهم … إستنزاف للوقت بشكل غير طبيعي … مرات كلاس كامل نحل فيه مسئلة وحده فقطططط !! أغلب الكلاسات يحط مثال على السبورة ويحله وبعدها يجيب سؤال ثاني معقد أكثر منه شوي ويقول يلا كل واحد يحل … ويشيك على كل طالب يشوف وش سوى … إذا ما راجعت محاضرته نصيحة لا تحضر المحاضرة اللي بعدها\n\nالنقطة الإيجابية الوحيدة فيه إنه ما يحضر … فأضطريت إني أسحب على آخر اسبوعين حالي حال أغلب الطلاب معه\n\nكوزاته قليلة جداا ومرات تكون مفاجئة وبدون ما يقولك قبلها … الظاهر هذا السمستر 4 كويزات أخذنا فقط وحذف أول واحد وصاروا 3 إذا ما خابني الظن فلازم تكون مركز بشكل كبير في الكويزات وتذاكر لها زين\n\nإذا كنت محتار بينه وبين مدرس آخر … أختر المدرس الآخر بدون تفكير لأني ما أتوقع فيه مدرس أسوء من كذا\n\nالتقييم النهائي: F-\n\nولا أحد يظن إني ما أخذت قريد حلو عشان كذا أسبه … بالعكس درجاتي ولله الحمد عالي العال وهذا بفضل الله ثم بفضل الدروس اللي يحطونها على الويب سي تي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p961414-ee201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/husain-al-dawish/98522/13", "user": "saudi_kfupm", "ts": 1325974236000, "tid": 98522, "pn": 13}}]}', 1325974236000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6130-ee201', 'stk-user6130', 'EE 201', 'doc', '{"docs": [{"id": "stk-dr-f98523", "n": "Dr. Jameel Bakhshwain", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله \" ee 201 \" سمستر 102 :\n\n1) الشرح : الرجال شريح بس عيبه إنه يحل أمثلة الأون لاين كورس بس و هي أمثلة سهلة جداً يعني عكس أسئلة المياجر و أسئلة الكتاب بس عموماً شرحه بطل.\n\n2) التحضير : يحضر غالباً بالأسماء و إذا في كويز يحضر عن طريقه بس إذا نزلت عنده انتبه ثم انتبه من الغياب لأن نهاية السمستر بيخصم على كل غياب درجة أما إذا كانت غيابتك اثنين أو أقل راح يعطيك زيادة واحدة في المية 🤠.\n\n3) الكوزات : عطانا 8 كوزات أخذ أحسن 6 أو 5 و الله إني ناسي بس كان مستواها متوسط .\n\nإضافات :\n\n* الدكتور باخشوين إذا اشتغلت معه صح يعني تبدع في الكوزات و تحل الهوموركات و ما تغيب ما راح يقصر معك نهائياً.\n\n* بالنسبة لتصحيحه أشوف عادي يعني يعطيك حقك لا أكثر و لا أقل.\n\nالقريد النهائي : +B .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p851703-ee201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jameel-bakhshwain/98523/15", "user": "user6130", "ts": 1307916938000, "tid": 98523, "pn": 15}}]}', 1307916938000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-eng.3booodii-ee201', 'stk-eng.3booodii', 'EE 201', 'doc', '{"docs": [{"id": "stk-dr-f98523", "n": "Dr. Jameel Bakhshwain", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE 201\n\nبنود التقييم :\n\nالتحضير : يحضر بداية المحاضرة غالباً وبعض الأحيان فـ النهاية ولما يكون فيه كويز يحضر به ( لو حضر وإنت منت موجود خلاص غايب إلا لو فاز الإتحاد شي ثاني 🤠 )\nطريقة الشرح :يشرح من الأون لاين ليكشرز … شرح ممتاز ورائع ويحل أمثلة السلايدز بس\nالكويزات : متوسطة ماهي صعبة\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A\nالصوت: واضح جداً ماشالله << شباب الشعراوي جمبنا يقولو صوته عندنا واصل ماشالله 🤠\nإضافات : دكتور محترم وأخلاق ومخلص جداً في عمله وتدريسه عكس كثير دكاترة … إلي ما عجبني فيه هو التصحيح … لكن إلي أسمعه إن أغلب دكاترة الكهربا زي كذا …\nبالنسبة للغياب … أنا نهاية السمستر عرفت إنه يخصم ع كل غياب درجة ! مدري المادة إسلامي ولا بي اي !", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p852230-ee201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jameel-bakhshwain/98523/16", "user": "eng.3boOodii", "ts": 1307962607000, "tid": 98523, "pn": 16}}]}', 1307962607000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulrahman.h-ee201', 'stk-abdulrahman.h', 'EE 201', 'doc', '{"docs": [{"id": "stk-dr-f98523", "n": "Dr. Jameel Bakhshwain", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ee201 - ee205\n\nأخذت مع الدكتور 201 وطلعت معه بأسوأ قريد لي في الجامعة … قلت بآخذ معه 205 عشان أوريه مستواي الحقيقي … طلعت بنفس القريد ><\"\n\nعيبه تصحيحه الشديد ، زي ما قالوا الشباب يا إما فل أو صفر و يحب أسئلة الخيارات و فل ان ذا بوكس لهذا السبب .\nهو فاهم جداً وشرحه زين لكن يغلب عليه حس الماث ، ويعتمد على الأونلاين لكتشر .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1123230-ee201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jameel-bakhshwain/98523/23", "user": "Abdulrahman.H", "ts": 1353787821000, "tid": 98523, "pn": 23}}]}', 1353787821000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ria-ee201', 'stk-ria', 'EE 201', 'doc', '{"docs": [{"id": "stk-dr-f98523", "n": "Dr. Jameel Bakhshwain", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE201-212\nالتحضير : ينادي بالاسامي واذا تاخرت ولو دقيقة خلاص متاخر (وللامانه شرح جبار)\nطريقة الشرح : يشرح من نوتات الحسون ويحلها بالايباد حقه\nالكويزات : هذا اللي يعيب الدكتور كويزات هذا الترم تجيب المرض نظامه وشو؟ ي فل ي صفر مافي بينهم يعطيك كويز علي البلاك بورد ي يكون اختيارات ي يكون اكتب الاجابة المشكلة انه اذا الجواب كان 8.1 وانت حاط 8.099 تاخذ صفر وكل كويز الافرج يكون ي 5 ي 6 بسبب الاصفار وهذا غير اذا ما صارخ عليك بنص الكويز\nالمياجر: كومن\nالفاينلات :كومن\nالقريد النهائي: C (يمشي الحال)\nالصوت: واضح\nإضافات : الدكتور شرحه حلو لكن لو تروح له تساله عن شيء منت فاهم بيصارخ عليك ومشكلته ينسى واجد فا اذا عندك عذر طبي ولا شيء بتراجعه فيه انشبله لانه يسنى.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534010-ee201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jameel-bakhshwain/98523/36", "user": "RIA", "ts": 1648348224000, "tid": 98523, "pn": 36}}]}', 1648348224000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ball_9-ee201', 'stk-ball_9', 'EE 201', 'doc', '{"docs": [{"id": "stk-dr-f115351", "n": "Dr. Ali T. Al-Awami", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE201 term111\nالدكتور روووعة وأخلاق\nيحضر تقريبا في الأسبوع مرة\nالكويزات يا إما صعبة مرة أو سهلة مرة\nالمياجر كومن\nالصوت واضح والأكسنت جيدة\nمتساهل في التصحيح", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p938809-ee201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-ali-t-al-awami/115351/5", "user": "ball_9", "ts": 1322492060000, "tid": 115351, "pn": 5}}]}', 1322492060000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6095-ee201', 'stk-user6095', 'EE 201', 'doc', '{"docs": [{"id": "stk-dr-f115351", "n": "Dr. Ali T. Al-Awami", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE201 term111\n\nالتحضير : في بدآية الترم … كآن يحضر بـ ذكر الأسمآء . أحيآنآ مآ يحضر … إلاآ إذآ كآن فيه غيآب وآضح\n\nطريقة الشرح : يشرح الكونسبت … و يحل إكزآمبلز\n\nالكويزات : متوسّطة … و أحيآنآ مآئلة للصعوبة …\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: A+\n\nالصوت: وآضح … و الأكسنت ممتازة\n\nإضافات : المدرس يُنصح به … فآهم و شريح", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p975605-ee201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-ali-t-al-awami/115351/7", "user": "user6095", "ts": 1327803881000, "tid": 115351, "pn": 7}}]}', 1327803881000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-dark_side-ee201', 'stk-dark_side', 'EE 201', 'doc', '{"docs": [{"id": "stk-dr-f176830", "n": "Dr. Ali Arshad Nasir", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE201-T221\n\nدكتور ممتاز الصراحه\n\nطريقة الشرح: دكتور علي ناصر طريقته يكتب لك القوانين حقت الدرس بالسبوره ويوريك اشتقاقها بعدين يستمر في حل المسائل، الدكتور يركز جدا ب جانب حل المسائل و انك تطلع من اللكتشر وانت تعرف شلون تحل و يجيب لك افكار رهيبه و صعبه، لكن مشكلته انه مايطري ابد جانب ربط اللي يسويه ب الحياه الواقعيه وهذا شيء الصراحه مهم بالنسبه لي لاني حاليا قاعد اتعامل مع السيركت كأنه ماث مادري وش فايدة الشي الفلاني او الطريقه الفلانيه\n\nالكويزات: اختبرنا ٥ كويزات و اشوف مستواها مابين المتوسط المرتفع إلى الصعب … هو يحاول يوزن الافرج حق الكلاس اذا شافه مرتفع جلدنا ب كويز واذا شافه منخفض سهل علينا الكويز و على هذا الحال .\n\nالمياجر: كومن\n\nالفاينلات: كومن\n\nالتصحيح: الصراحه تصحيحه ممتاز ب اسئلة الرتن كم مره اجيب حل نهائي غلط بالكويز و يعطيني درجه كامله او حولها عشاني حليت ب طريقه صحيحه بس الارقام ماطلعت معي… بخصوص تصحيح اسئلة الرتن ب المياجر و الفاينل الصراحه الدكتور عطاني حقي و زود و اذا حسيت درجتك فيها شيء غلط رح راجعه .يستقبلك ب صدر رحب و يعطيك ورقة الفاينل و بيراجع معك وفي حال وضح فيه سوء فهم بالتصحيخ راح يعدل و يزودك بإذن الله\n\nالصوت: عادي بس اذا بتجلس ورى ممكن ماتسمعه بوضوح\n\nالقريد النهائي : A+ ولو فيه زود يستاهلها\n\nإضافات: الدكتور حبيب جدا جدا تتعب و انت تقول حبيب و لا توفيه حقه، ومتعاون بخصوص تأجيل الكويزات و الواجبات مره\n\nالتحضير: يحضر ب بداية الكلاس ب منادات الاسماء … و يعطيك غيابين مجانيه وبعدها يبدأ يخصم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536065-ee201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ali-arshad-nasir/176830/9", "user": "Dark_Side", "ts": 1672112763000, "tid": 176830, "pn": 9}}]}', 1672112763000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
